299:export const scalableSecurityTrades = pgTable("scalable_security_trades", {
308:  index("scalable_security_trades_isin").on(table.workspaceId, table.isin, table.occurredAt),
309:  check("scalable_security_trades_provider_id_check", sql`char_length(${table.providerId}) between 1 and 200`),
310:  check("scalable_security_trades_isin_check", sql`${table.isin} ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'`),
