import Link from "next/link";
import { formatMoney } from "@/lib/finance/format";
import type { ScalablePortfolio } from "@/lib/scalable/portfolio";

const TIMEFRAMES = [["INTRADAY", "Latest market day"], ["ONE_WEEK", "1 week"], ["ONE_MONTH", "1 month"], ["THREE_MONTHS", "3 months"], ["YEAR_TO_DATE", "This year"], ["ONE_YEAR", "1 year"], ["MAX", "All time"]] as const;

export function ScalablePortfolioView({ portfolio, locale }: { portfolio: ScalablePortfolio; locale?: string }) {
  const money = (minor: string) => formatMoney(minor, portfolio.currency, locale);
  const returns = TIMEFRAMES.flatMap(([key, label]) => { const entry = portfolio.performance.find(item => item.timeframe === key); return entry ? [{ label, minor: entry.returnMinor }] : []; });
  return <div className="space-y-3 text-sm">
    <div>
      <p className="text-xs text-muted-foreground">Portfolio value on {portfolio.asOf}</p>
      <p className="font-mono text-2xl font-semibold tabular-nums">{money(portfolio.totalMinor)}</p>
    </div>
    <dl className="grid grid-cols-3 gap-3">
      {([["Securities", portfolio.securitiesMinor], ["Crypto", portfolio.cryptoMinor], ["Cash", portfolio.cashMinor]] as const).map(([label, minor]) =>
        <div key={label}><dt className="text-xs text-muted-foreground">{label}</dt><dd className="font-mono tabular-nums">{money(minor)}</dd></div>)}
    </dl>
    {returns.length > 0 && <div>
      <p className="text-xs text-muted-foreground">Gain or loss</p>
      <dl className="mt-1 grid grid-cols-3 gap-3 sm:grid-cols-7">{returns.map(entry => <div key={entry.label}><dt className="text-xs text-muted-foreground">{entry.label}</dt>
        <dd className={`font-mono tabular-nums ${BigInt(entry.minor) < 0n ? "text-danger" : BigInt(entry.minor) > 0n ? "text-success" : ""}`}>{BigInt(entry.minor) > 0n ? "+" : ""}{money(entry.minor)}</dd></div>)}</dl>
    </div>}
    <Link href="/money/wealth" className="inline-block text-brand underline-offset-4 hover:underline">See positions, chart and activity on Wealth</Link>
  </div>;
}
"use client";
import { useState } from "react";
import { NetWorthChart } from "@/components/net-worth-chart";
import type { PositionChartView } from "@/lib/scalable/chart-view";

const DEFAULT_PERIOD = "one_month";
const TONE = { up: "text-success", down: "text-danger", flat: "text-muted-foreground" };

export function ScalablePositionChart({ name, views }: { name: string; views: PositionChartView }) {
  const [key, setKey] = useState(() => views.find(view => view.key === DEFAULT_PERIOD)?.key ?? views[0]?.key);
  const view = views.find(entry => entry.key === key);
  if (!view) return <p className="text-sm text-muted-foreground">No price chart is stored yet. It appears after the next Scalable sync.</p>;
  return <div className="space-y-3">
    <div role="group" aria-label="Chart period" className="flex gap-1.5">{views.map(entry =>
      <button key={entry.key} type="button" aria-pressed={entry.key === view.key} onClick={() => setKey(entry.key)}
        className={`min-h-11 min-w-11 rounded-lg border px-3 text-sm ${entry.key === view.key ? "border-brand bg-brand/10 font-medium text-foreground" : "border-border text-muted-foreground hover:text-foreground"}`}>{entry.label}</button>)}</div>
    {view.change && <p className={`font-mono text-sm tabular-nums ${TONE[view.change.direction]}`}>{view.change.text} <span className="font-sans text-muted-foreground">over {view.label}</span></p>}
    <NetWorthChart label={`${name} price, ${view.label}`} points={view.points} markers={view.markers} />
    {view.markers.length > 0 && <ul aria-label="Your trades in this period" className="space-y-0.5 text-xs text-muted-foreground">{view.markers.map((marker, order) =>
      <li key={order} className="flex items-center gap-1.5"><span aria-hidden="true" className={`size-2 rounded-full ${marker.side === "BUY" ? "bg-success" : "bg-danger"}`} />{marker.label}</li>)}</ul>}
    <p className="text-xs text-muted-foreground">As of {view.asOf}, from the last Scalable sync.</p>
  </div>;
}
"use client";
import { useEffect, useState } from "react";

type News = { summary: string | null; detail: string | null };
type State = { status: "loading" } | { status: "ready"; news: News } | { status: "error"; message: string };

export function ScalablePositionNews({ isin }: { isin: string }) {
  const [state, setState] = useState<State>({ status: "loading" });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const controller = new AbortController();
    fetch(`/api/scalable/news?isin=${encodeURIComponent(isin)}`, { cache: "no-store", signal: controller.signal })
      .then(async response => {
        const body = await response.json().catch(() => ({})) as Partial<News> & { error?: string };
        setState(response.ok ? { status: "ready", news: { summary: body.summary ?? null, detail: body.detail ?? null } } : { status: "error", message: body.error ?? "Scalable could not load the news." });
      })
      .catch(() => { if (!controller.signal.aborted) setState({ status: "error", message: "You look to be offline, so Moneo can't ask Scalable for the news." }); });
    return () => controller.abort();
  }, [isin, attempt]);
  return <section aria-labelledby="position-news" aria-busy={state.status === "loading"} className="space-y-2">
    <h3 id="position-news" className="text-xs font-medium text-muted-foreground">News from Scalable</h3>
    {state.status === "loading" && <div role="status" className="space-y-2"><span className="sr-only">Loading news…</span><div className="h-3 w-full animate-pulse rounded bg-muted" /><div className="h-3 w-4/5 animate-pulse rounded bg-muted" /></div>}
    {state.status === "ready" && (state.news.summary || state.news.detail
      ? <div className="space-y-2 text-sm">{state.news.summary && <p className="font-medium">{state.news.summary}</p>}{state.news.detail && <p className="whitespace-pre-line text-muted-foreground">{state.news.detail}</p>}</div>
      : <p className="text-sm text-muted-foreground">Scalable has no news for this security right now.</p>)}
    {state.status === "error" && <div role="alert" className="space-y-1 text-sm"><p>{state.message}</p><p className="text-xs text-muted-foreground">The chart above is from the last sync and works without a connection.</p>
      <button type="button" onClick={() => { setState({ status: "loading" }); setAttempt(count => count + 1); }} className="min-h-11 text-sm font-medium text-brand underline">Try again</button></div>}
  </section>;
}
import Link from "next/link";
import { NetWorthChart } from "@/components/net-worth-chart";
import { displayFormat } from "@/lib/display-format";
import { calendarDate } from "@/lib/finance/calendar";
import type { WealthItem } from "@/lib/finance/wealth";
import { PERIODS, toMinor } from "@/lib/scalable/live";
import type { ScalablePortfolio } from "@/lib/scalable/portfolio";

type Point = { date: string; value: bigint };
const signed = (minor: bigint, text: string) => minor > 0n ? `+${text}` : text;
const tone = (minor: bigint) => minor > 0n ? "text-success" : minor < 0n ? "text-danger" : "text-muted-foreground";
const pct = (part: bigint, whole: bigint) => whole > 0n ? Number(part * 10000n / whole) / 100 : null;
const pctText = (value: number | null) => value === null ? "" : `${value > 0 ? "+" : ""}${value.toLocaleString("en", { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%`;
const SHADES = ["bg-brand", "bg-brand/75", "bg-brand/55", "bg-brand/40", "bg-brand/25", "bg-amber-500/70"];

export function ScalableInvestments({ portfolio, positions, history, calculatedBefore, historyFailed, syncedAt, active, locale, timeZone, positionLinks = {} }: {
  portfolio: ScalablePortfolio; positions: WealthItem[]; history: Point[]; calculatedBefore: string | null; historyFailed: boolean; syncedAt: string | null; active: boolean; locale: string; timeZone: string; positionLinks?: Record<string, string>;
}) {
  const { money, date, dateTime } = displayFormat(locale, timeZone);
  const cur = portfolio.currency, show = (minor: bigint | string) => money(minor, cur);
  const total = BigInt(portfolio.totalMinor);
  const today = portfolio.performance.find(entry => entry.timeframe === "INTRADAY");
  const todayMinor = today ? BigInt(today.returnMinor) : null;
  const movedOn = portfolio.valuedAt ? calendarDate(portfolio.valuedAt, timeZone) : null;
  const moveLabel = !movedOn || movedOn === calendarDate(new Date(), timeZone) ? "today" : `on ${date(movedOn)}`;
  const periods = Object.entries(PERIODS).filter(([key]) => key !== "INTRADAY").flatMap(([key, label]) => {
    const entry = portfolio.performance.find(item => item.timeframe === key); return entry ? [{ label, minor: BigInt(entry.returnMinor) }] : []; });
  const slices = [...positions.map(item => ({ name: item.name, minor: BigInt(item.amount_minor) })),
    ...(BigInt(portfolio.cryptoMinor) > 0n ? [{ name: "Crypto", minor: BigInt(portfolio.cryptoMinor) }] : [])].sort((a, b) => Number(b.minor - a.minor));
  const cash = BigInt(portfolio.cashMinor);
  const first = calculatedBefore ? undefined : history[0]?.value, change = first === undefined ? null : total - first;

  return <section aria-labelledby="scalable-heading" className="space-y-5 rounded-xl border border-border bg-card p-6">
    <div className="flex flex-wrap items-baseline justify-between gap-2">
      <h2 id="scalable-heading" className="text-sm font-medium">Scalable Capital</h2>
      <p className="text-xs text-muted-foreground">{active ? "Synced" : "Login ended, showing the last sync"}{syncedAt ? ` ${dateTime(syncedAt)}` : ""} · <Link href="/money/accounts#scalable" className="text-brand hover:underline">Sync or manage</Link></p>
    </div>

    <div>
      <p className="break-words font-mono text-3xl font-semibold tracking-tight tabular-nums sm:text-4xl">{show(total)}</p>
      {todayMinor !== null && <p className={`mt-1 font-mono text-sm tabular-nums ${tone(todayMinor)}`}>{signed(todayMinor, show(todayMinor))} {pctText(pct(todayMinor, total - todayMinor))} <span className="font-sans text-muted-foreground">{moveLabel}</span></p>}
    </div>

    {periods.length > 0 && <ul aria-label="Gain or loss by period" className="flex flex-wrap gap-2">{periods.map(period =>
      <li key={period.label} className="rounded-lg border border-border px-3 py-1.5"><span className="block text-xs text-muted-foreground">{period.label}</span>
        <span className={`font-mono text-sm tabular-nums ${tone(period.minor)}`}>{signed(period.minor, show(period.minor))}</span></li>)}</ul>}

    <div>
      {history.length >= 2 ? <>
        <NetWorthChart label={`Scalable portfolio value in ${cur} by day`} points={history.map(point => ({ date: point.date, label: date(point.date), amount: show(point.value), y: Number(point.value) }))} />
        <p className="mt-1 flex justify-between text-xs text-muted-foreground"><span>{date(history[0].date)}</span>
          {change !== null && <span className={tone(change)}>{signed(change, show(change))} since then</span>}<span>Today</span></p>
        {calculatedBefore && <p className="mt-2 text-xs text-muted-foreground">Days before {date(calculatedBefore)} are calculated from your transactions and past prices. Prices further than a year back are monthly.</p>}
      </> : <p className="text-sm text-muted-foreground">The value chart fills in day by day as Moneo syncs Scalable.</p>}
      {historyFailed && <p className="mt-2 text-xs text-muted-foreground">{calculatedBefore ? "The latest check of these calculated days failed, so older days show the last good run." : "Earlier days could not be worked out, so this chart starts at your first sync."}</p>}
    </div>

    {total > 0n && <div>
      <div className="flex h-3 w-full overflow-hidden rounded-full bg-muted" aria-hidden>
        {slices.map((slice, index) => <span key={slice.name} className={SHADES[index % SHADES.length]} style={{ width: `${Number(slice.minor * 10000n / total) / 100}%` }} />)}
        {cash > 0n && <span className="bg-muted-foreground/30" style={{ width: `${Number(cash * 10000n / total) / 100}%` }} />}
      </div>
      <ul aria-label="Where the money is" className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
        {slices.map((slice, index) => <li key={slice.name} className="flex items-center gap-1.5"><span className={`size-2 rounded-full ${SHADES[index % SHADES.length]}`} />{slice.name} {pct(slice.minor, total)?.toFixed(0)}%</li>)}
        {cash > 0n && <li className="flex items-center gap-1.5"><span className="size-2 rounded-full bg-muted-foreground/30" />Cash {pct(cash, total)?.toFixed(0)}%</li>}
      </ul>
    </div>}

    <div className="divide-y divide-border rounded-lg border border-border">
      {positions.map(item => {
        const value = BigInt(item.amount_minor), gain = item.cost_basis_minor === null ? null : value - BigInt(item.cost_basis_minor);
        const isin = positionLinks[item.id];
        return <div key={item.id} className="relative flex items-start justify-between gap-3 px-4 py-3">
          <div className="min-w-0"><p className="truncate font-medium">{isin ? <Link href={`/money/wealth?position=${isin}`} scroll={false} className="after:absolute after:inset-0 hover:underline" aria-label={`${item.name}: price chart and news`}>{item.name}</Link> : item.name}</p>
            <p className="text-xs text-muted-foreground">{item.quantity_text} × {item.unit_price_text ? money(toMinor(item.unit_price_text, item.currency_code), item.currency_code) : "—"}</p></div>
          <div className="shrink-0 text-right"><p className="font-mono tabular-nums">{money(value, item.currency_code)}</p>
            {gain !== null && <p className={`font-mono text-xs tabular-nums ${tone(gain)}`}>{signed(gain, money(gain, item.currency_code))} {pctText(pct(gain, BigInt(item.cost_basis_minor!)))}</p>}</div>
        </div>;
      })}
      {BigInt(portfolio.cryptoMinor) > 0n && <div className="flex justify-between gap-3 px-4 py-3"><p className="font-medium">Crypto</p><p className="font-mono tabular-nums">{show(portfolio.cryptoMinor)}</p></div>}
      <div className="flex justify-between gap-3 px-4 py-3"><div><p className="font-medium">Cash to invest</p></div><p className="font-mono tabular-nums">{show(cash)}</p></div>
    </div>

    {(portfolio.activity?.length ?? 0) > 0 && <div>
      <h3 className="text-xs font-medium text-muted-foreground">Recent activity</h3>
      <ul className="mt-2 space-y-1.5 text-sm">{portfolio.activity!.slice(0, 5).map(row => {
        const amount = row.amountMinor === null ? null : BigInt(row.amountMinor);
        return <li key={row.id} className="flex items-baseline justify-between gap-3">
          <span className="min-w-0 truncate"><span className="font-mono text-xs text-muted-foreground">{date(row.date)}</span> <span className="capitalize">{row.type}</span>{row.shares ? ` ${row.shares} ×` : ""} <span className="text-muted-foreground">{row.description}</span>{row.status !== "SETTLED" ? <span className="text-xs text-warning"> · {row.status.toLowerCase()}</span> : null}</span>
          {amount !== null && <span className={`shrink-0 font-mono tabular-nums ${amount > 0n ? "text-success" : ""}`}>{signed(amount, money(amount, row.currencyCode))}</span>}</li>;
      })}</ul>
    </div>}

    {(portfolio.watchlist?.length ?? 0) > 0 && <div>
      <h3 className="text-xs font-medium text-muted-foreground">Watchlist</h3>
      <ul className="mt-2 flex flex-wrap gap-2 text-sm">{portfolio.watchlist!.map(item => <li key={item.isin} className="rounded-lg border border-border px-3 py-1.5">
