const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
const text = (value: number | string) => typeof value === "number" ? decimalText(value) : value;
const nextCursor = z.object({ nextCursor: z.string().nullish() });
const transactionsSchema = z.object({
  page: nextCursor.optional(),
  transactions: z.array(z.object({ id: z.string(), status: z.string(), currency: z.string().nullish(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
    security: z.object({ isin: z.string(), side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() }).nullish(),
    cash: z.object({ amount: decimal.nullish() }).nullish(),
    nonTradeSecurity: z.object({ isin: z.string(), transactionType: z.string().nullish(), quantity: decimal.nullish() }).nullish() })).default([]),
  crypto: z.object({ page: nextCursor.optional(), transactions: z.array(z.object({ id: z.string(), status: z.string(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
    side: z.string().nullish(), quantity: decimal.nullish(), amount: decimal.nullish() })).default([]) }).nullish(),
});
const holdingsSchema = z.object({
  holdings: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }), currentQuote: z.object({ currency: z.string() }) })).default([]),
  cryptoHoldings: z.array(z.object({ ticker: z.string(), position: z.object({ filled: decimal }).nullish(), etpPositions: z.array(z.object({ isin: z.string(), position: z.object({ filled: decimal }).nullish() })).nullish() })).default([]),
});
const chartSchema = z.object({ currency: z.string().nullish(), dataPoints: z.array(z.object({ midPrice: decimal.nullish(), timestampUtc: z.string() })).default([]) });
const detailsSchema = z.object({ transaction: z.object({ security: z.object({ isin: z.string() }), securityTrade: z.object({ averagePrice: decimal.nullish() }).nullish() }) });
export type TradeDetail = { isin: string; price: string | null };
export type TradeDetails = { known: Map<string, TradeDetail>; remember: (id: string, detail: TradeDetail) => Promise<void> };
const settled = (row: { status: string; isCancellation?: boolean | null }) => row.status === "SETTLED" && !row.isCancellation;

async function readRows(mcp: Pick<ScalableMcp, "callTool">, details: TradeDetails) {
  const securities = new Map<string, HistoryRow>(), crypto = new Map<string, Omit<Extract<HistoryRow, { kind: "crypto" }>, "isin">>();
  let cursor: string | undefined, cryptoCursor: string | undefined, securitiesDone = false, cryptoDone = false;
  for (let page = 0; !securitiesDone || !cryptoDone; page++) {
    if (page === MAX_PAGES) throw new Error("Scalable transactions never finished paging");
    const reply = transactionsSchema.parse(await mcp.callTool("list_portfolio_transactions", { pageSize: PAGE_SIZE, ...(cursor ? { cursor } : {}), ...(cryptoCursor ? { cryptoCursor } : {}) }));
    if (!securitiesDone) for (const row of reply.transactions.filter(settled)) {
      const base = { id: row.id, at: row.lastEventAt, ...(row.currency ? { currency: row.currency } : {}) };
      if (row.security) securities.set(row.id, { ...base, kind: "security", isin: row.security.isin, side: row.security.side ?? "unknown", quantity: row.security.quantity == null ? null : text(row.security.quantity), amountText: String(row.security.amount ?? 0) });
      else if (row.cash) securities.set(row.id, { ...base, kind: "cash", amountText: String(row.cash.amount ?? 0) });
      else if (row.nonTradeSecurity) securities.set(row.id, { ...base, kind: "shares", isin: row.nonTradeSecurity.isin, side: row.nonTradeSecurity.transactionType ?? "unknown",
        quantity: row.nonTradeSecurity.quantity == null ? null : text(row.nonTradeSecurity.quantity) });
    }
    if (!cryptoDone) for (const row of (reply.crypto?.transactions ?? []).filter(settled))
      crypto.set(row.id, { id: row.id, at: row.lastEventAt, kind: "crypto", side: row.side ?? "unknown", quantity: row.quantity == null ? null : text(row.quantity), amountText: String(row.amount ?? 0) });
    cursor = securitiesDone ? undefined : reply.page?.nextCursor || undefined;
    cryptoCursor = cryptoDone ? undefined : reply.crypto?.page?.nextCursor || undefined;
    securitiesDone = !cursor; cryptoDone = !cryptoCursor;
  }
  const detail = async (id: string) => {
    const saved = details.known.get(id);
    if (saved) return saved;
    const { security, securityTrade } = detailsSchema.parse(await mcp.callTool("get_transaction_details", { transactionId: id })).transaction;
    const price = securityTrade?.averagePrice != null && Number(securityTrade.averagePrice) > 0 ? text(securityTrade.averagePrice) : null;
    const found = { isin: security.isin, price };
    await details.remember(id, found);
    return found;
  };
  const rows: HistoryRow[] = [];
  for (const row of securities.values()) rows.push(row.kind === "security" ? { ...row, price: (await detail(row.id)).price } : row);
  for (const row of crypto.values()) { const { isin, price } = await detail(row.id); rows.push({ ...row, isin, price }); }
  return rows;
}

async function readChart(mcp: Pick<ScalableMcp, "callTool">, isin: string): Promise<Chart> {
  const replies: z.infer<typeof chartSchema>[] = [];
  for (const timeframe of TIMEFRAMES) replies.push(chartSchema.parse(await mcp.callTool("get_security_chart", { isin, timeframe })));
  const points = new Map(replies.flatMap(reply => reply.dataPoints.flatMap(point => point.midPrice != null && Number(point.midPrice) > 0 ? [[point.timestampUtc, text(point.midPrice)] as const] : [])));
  return { currency: replies.find(reply => reply.dataPoints.length && reply.currency !== CURRENCY)?.currency ?? CURRENCY, points: [...points].map(([at, price]) => ({ at, price })) };
}

export async function readHistoryInput(mcp: Pick<ScalableMcp, "callTool">, timeZone: string, before: string, details: TradeDetails): Promise<HistoryInput> {
  const rows = await readRows(mcp, details);
  const holdings = holdingsSchema.parse(await mcp.callTool("get_portfolio_holdings"));
  const cash = z.object({ cash: z.object({ cashBalance: decimal }) }).parse(await mcp.callTool("get_portfolio_cash_breakdown"));
  const unbacked = holdings.cryptoHoldings.find(coin => Number(coin.position?.filled ?? 0) > 0 && !coin.etpPositions?.some(etp => Number(etp.position?.filled ?? 0) > 0));
  if (unbacked) throw new Error(`${unbacked.ticker} is held without an ETP position`);
  const held = [...holdings.holdings.map(holding => ({ isin: holding.isin, filled: holding.position.filled, currency: holding.currentQuote.currency })),
    ...holdings.cryptoHoldings.flatMap(coin => (coin.etpPositions ?? []).flatMap(etp => etp.position ? [{ isin: etp.isin, filled: etp.position.filled }] : []))];
  const stillHeld = new Set(held.filter(holding => Number(holding.filled) > 0).map(holding => holding.isin));
  const priced = new Set(rows.flatMap(row => row.kind === "security" || row.kind === "crypto" || (row.kind === "shares" && stillHeld.has(row.isin)) ? [row.isin] : []));
  const charts: Record<string, Chart> = {};
  for (const isin of priced) charts[isin] = await readChart(mcp, isin);
  return { rows, charts, timeZone, before, cashBalance: cash.cash.cashBalance, holdings: held };
}

const SHARE_MOVES = /_(IN|OUT)$/;
const ONE = 10n ** 18n, TOLERANCE = 10n ** 12n, CASH_TOLERANCE = 100n;
const CENTS = 100n, CENT_SCALE = ONE / CENTS;
const scaled = (value: number | string) => { const ratio = decimalRatio(text(value)); return ratio.numerator * ONE / ratio.denominator; };
const decimalOf = (value: bigint) => `${value / ONE}.${(value % ONE).toString().padStart(18, "0")}`;
const value = (quantity: bigint, price: bigint) => holdingValue(decimalOf(quantity), decimalOf(price), CURRENCY);
const absolute = (minor: bigint) => minor < 0n ? -minor : minor;
type Trade = Extract<HistoryRow, { kind: "security" | "crypto" }>;
const tradePrices = (rows: Trade[]) => rows.flatMap(row => {
  if (row.price) return [{ at: row.at, price: scaled(row.price) }];
  const minor = BigInt(toMinor(row.amountText, CURRENCY)), quantity = scaled(row.quantity!);
  return minor !== 0n && quantity > 0n ? [{ at: row.at, price: absolute(minor) * CENT_SCALE * ONE / quantity }] : [];
});

type Prices = { points: { day: string; at: number; price: bigint }[]; next: number; current: bigint | null };
function pricesFrom(chart: Chart | undefined, timeZone: string, trades: { at: string; price: bigint }[] = []): Prices {
  const points = [...(chart?.points ?? []).map(point => ({ at: point.at, price: scaled(point.price) })), ...trades]
    .map(point => ({ day: calendarDate(point.at, timeZone), at: Date.parse(point.at), price: point.price })).sort((a, b) => a.at - b.at);
  return { points, next: 0, current: null };
}
function priceOn(prices: Prices, date: string) {
  while (prices.next < prices.points.length && prices.points[prices.next].day <= date) prices.current = prices.points[prices.next++].price;
  return prices.current;
}

function replay(input: HistoryInput): HistoryResult {
  const fail = (reason: string): HistoryResult => ({ ok: false, reason });
  const rows = [...input.rows].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  if (!rows.length) return fail("Scalable returned no settled transactions");

  for (const row of rows) {
    if (row.currency && row.currency !== CURRENCY) return fail(`A transaction is in ${row.currency}, and only ${CURRENCY} is supported`);
    if (row.kind === "cash") continue;
    if (row.kind === "shares" ? !SHARE_MOVES.test(row.side) : row.side !== "BUY" && row.side !== "SELL") return fail(`Transaction ${row.id} has an unknown side: ${row.side}`);
    if (row.quantity === null) return fail(`Transaction ${row.id} has no quantity`);
  }
  for (const [isin, chart] of Object.entries(input.charts)) if (chart.currency !== CURRENCY) return fail(`${isin} is priced in ${chart.currency}, and only ${CURRENCY} is supported`);
  for (const holding of input.holdings) if (holding.currency && holding.currency !== CURRENCY && Number(holding.filled) > 0) return fail(`${holding.isin} is priced in ${holding.currency}, and only ${CURRENCY} is supported`);

  const trades = rows.filter((row): row is Trade => row.kind === "security" || row.kind === "crypto");
  const cryptoIsins = new Set(trades.filter(row => row.kind === "crypto").map(row => row.isin));
  const shares = new Map<string, bigint>(), prices = new Map<string, Prices>();
  for (const isin of new Set(rows.flatMap(row => row.kind === "cash" ? [] : [row.isin]))) {
    shares.set(isin, 0n);
    prices.set(isin, pricesFrom(input.charts[isin], input.timeZone, tradePrices(trades.filter(row => row.isin === isin))));
  }

  const byDay = new Map<string, HistoryRow[]>();
  for (const row of rows) {
    const day = calendarDate(row.at, input.timeZone);
    byDay.set(day, [...(byDay.get(day) ?? []), row]);
  }
  const eventDays = [...byDay.keys()].sort(), first = eventDays[0], lastEvent = eventDays.at(-1)!;
  const dayBefore = new Date(Date.parse(`${input.before}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);

  const days: HistoryDay[] = [];
  let cashMinor = 0n;
  for (const date of dayRange(first, lastEvent > dayBefore ? lastEvent : dayBefore)) {
    for (const row of byDay.get(date) ?? []) {
      if (row.kind !== "shares") cashMinor += BigInt(toMinor(row.amountText, CURRENCY));
      if (row.kind === "cash") continue;
      const quantity = scaled(row.quantity!);
      shares.set(row.isin, shares.get(row.isin)! + (row.side === "BUY" || row.side.endsWith("_IN") ? quantity : -quantity));
    }
    for (const [isin, held] of shares) if (held < -TOLERANCE) return fail(`Shares of ${isin} go negative on ${date}`);
    if (date > dayBefore) continue;

    let securitiesMinor = 0n, cryptoMinor = 0n;
    for (const [isin, held] of shares) {
      if (held <= TOLERANCE) continue;
      const price = priceOn(prices.get(isin)!, date);
      if (price === null) return fail(`${isin} has no price on ${date}`);
      if (cryptoIsins.has(isin)) cryptoMinor += value(held, price);
      else securitiesMinor += value(held, price);
    }
    days.push({ date, securitiesMinor, cryptoMinor, cashMinor, totalMinor: securitiesMinor + cryptoMinor + cashMinor });
  }

  for (const isin of new Set([...shares.keys(), ...input.holdings.map(holding => holding.isin)])) {
    const held = input.holdings.find(holding => holding.isin === isin)?.filled ?? 0, replayed = shares.get(isin) ?? 0n;
    if (absolute(replayed - scaled(held)) > TOLERANCE) return fail(`Shares of ${isin} replay to ${decimalOf(replayed)}, but Scalable holds ${text(held)}`);
  }
  const balance = BigInt(toMinor(input.cashBalance, CURRENCY));
  if (absolute(cashMinor - balance) > CASH_TOLERANCE) return fail(`Cash replays to ${cashMinor} cents, but Scalable holds ${balance}`);
  return { ok: true, days: days.filter(day => day.date < input.before) };
}

export function calculateHistory(input: HistoryInput): HistoryResult {
  try { return replay(input); } catch (error) { return { ok: false, reason: error instanceof Error ? error.message : "The transactions could not be read" }; }
}
import { z } from "zod";
import { serviceDb } from "@/lib/service-db";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { ScalableMcp } from "./client";
import type { HistoryRow } from "./history";
import { decimalText } from "./portfolio";

export const CHART_PERIODS = [["one_day", "1D"], ["seven_days", "1W"], ["one_month", "1M"], ["one_year", "1Y"], ["max", "Max"]] as const;
export type ChartTimeframe = (typeof CHART_PERIODS)[number][0];
export type ChartPoint = { at: string; price: string };
export type ChartRow = { isin: string; timeframe: ChartTimeframe; currency_code: string; points: ChartPoint[]; fetched_at: string };
export type TradeRow = { provider_id: string; isin: string; side: "BUY" | "SELL"; occurred_at: string; quantity_text: string };
export type PositionChart = { periods: { timeframe: ChartTimeframe; label: string; currency: string; points: ChartPoint[]; fetchedAt: string }[]; trades: { at: string; side: "BUY" | "SELL"; quantity: string }[] };

const MAX_POINTS = 240, CONCURRENCY = 4;
const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
const decimalString = /^[0-9]+(\.[0-9]+)?$/;
const text = (value: number | string) => typeof value === "number" ? decimalText(value) : value.replace(/^-/, "");
const chartSchema = z.object({ currency: z.string().regex(/^[A-Z]{3}$/), dataPoints: z.array(z.object({ midPrice: decimal.nullish(), timestampUtc: z.string() })).default([]) });
const storedPoints = z.array(z.object({ at: z.string(), price: z.string().regex(decimalString) }));
const listSchema = z.object({ transactions: z.array(z.object({ id: z.string().min(1), status: z.string(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(),
  security: z.object({ isin: z.string(), side: z.string().nullish(), quantity: decimal.nullish() }).nullish() })).default([]) });

export function thinned<T>(points: T[], limit = MAX_POINTS): T[] {
  if (points.length <= limit) return points;
  return Array.from({ length: limit }, (_, index) => points[Math.round(index * (points.length - 1) / (limit - 1))]);
}

async function readChart(mcp: Pick<ScalableMcp, "callTool">, isin: string, timeframe: ChartTimeframe, fetchedAt: string): Promise<ChartRow | null> {
  const chart = chartSchema.parse(await mcp.callTool("get_security_chart", { isin, timeframe }));
  const points = new Map(chart.dataPoints.flatMap(point => point.midPrice != null && Number(point.midPrice) > 0 && !Number.isNaN(Date.parse(point.timestampUtc))
    ? [[new Date(point.timestampUtc).toISOString(), text(point.midPrice)] as const] : []));
  if (!points.size) return null;
  return { isin, timeframe, currency_code: chart.currency, fetched_at: fetchedAt,
    points: thinned([...points].sort(([a], [b]) => Date.parse(a) - Date.parse(b)).map(([at, price]) => ({ at, price }))) };
}

export async function readCharts(mcp: Pick<ScalableMcp, "callTool">, isins: string[], fetchedAt: string) {
  const jobs = isins.flatMap(isin => CHART_PERIODS.map(([timeframe]) => ({ isin, timeframe })));
  const rows: ChartRow[] = [];
  let failed = 0, next = 0;
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, jobs.length) }, async () => {
    while (next < jobs.length) {
      const job = jobs[next++];
      try { const row = await readChart(mcp, job.isin, job.timeframe, fetchedAt); if (row) rows.push(row); } catch { failed++; }
    }
  }));
  return { rows, failed };
}

export function tradeRows(reply: unknown): TradeRow[] {
  return listSchema.parse(reply).transactions.flatMap(row => {
    const side = row.security?.side?.toUpperCase(), quantity = row.security?.quantity == null ? null : text(row.security.quantity);
    if (row.status !== "SETTLED" || row.isCancellation || (side !== "BUY" && side !== "SELL") || !quantity || !decimalString.test(quantity) || Number(quantity) <= 0) return [];
    return [{ provider_id: row.id, isin: row.security!.isin, side, occurred_at: row.lastEventAt, quantity_text: quantity }];
  });
}

export function historyTradeRows(rows: HistoryRow[]): TradeRow[] {
  return rows.flatMap(row => {
    const quantity = row.kind === "security" ? row.quantity?.replace(/^-/, "") : undefined;
    return row.kind === "security" && (row.side === "BUY" || row.side === "SELL") && quantity && decimalString.test(quantity) && Number(quantity) > 0
      ? [{ provider_id: row.id, isin: row.isin, side: row.side, occurred_at: row.at, quantity_text: quantity }] : [];
  });
}

export async function saveCharts(connectionId: string, saved: { charts: ChartRow[]; trades: TradeRow[]; held: string[] | null }) {
  const { error } = await serviceDb().rpc("save_scalable_charts", { p_connection_id: connectionId, p_charts: saved.charts, p_trades: saved.trades, p_held: saved.held });
  if (error) throw new Error(error.message);
}

export async function removeCharts(workspaceId: string) {
  const { error } = await serviceDb().rpc("remove_scalable_charts", { p_workspace_id: workspaceId });
  if (error) throw new Error(error.message);
}

export async function chartedIsins(db: SupabaseClient, workspaceId: string) {
  const { data, error } = await db.from("scalable_security_charts").select("isin").eq("workspace_id", workspaceId);
  if (error) throw new Error(error.message);
  return new Set((data ?? []).map(row => row.isin as string));
}

export async function loadPositionChart(db: SupabaseClient, workspaceId: string, isin: string): Promise<PositionChart> {
  const [charts, trades] = await Promise.all([
    db.from("scalable_security_charts").select("timeframe, currency_code, points, fetched_at").eq("workspace_id", workspaceId).eq("isin", isin),
    db.from("scalable_security_trades").select("side, occurred_at, quantity_text").eq("workspace_id", workspaceId).eq("isin", isin).order("occurred_at"),
  ]);
  for (const result of [charts, trades]) if (result.error) throw new Error(result.error.message);
  return {
    periods: CHART_PERIODS.flatMap(([timeframe, label]) => {
      const row = (charts.data ?? []).find(entry => entry.timeframe === timeframe);
      const points = row ? storedPoints.safeParse(row.points) : null;
      return row && points?.success && points.data.length ? [{ timeframe, label, currency: row.currency_code as string, points: points.data, fetchedAt: row.fetched_at as string }] : [];
    }),
    trades: (trades.data ?? []).map(row => ({ at: row.occurred_at as string, side: row.side as "BUY" | "SELL", quantity: row.quantity_text as string })),
  };
}
import type { PositionChart } from "./charts";
import { toMinor } from "./live";

type Format = { money: (minor: bigint | string, currency: string) => string; dateTime: (value: string) => string };
export type PositionChartView = { key: string; label: string; asOf: string; change: { text: string; direction: "up" | "down" | "flat" } | null;
  points: { date: string; label: string; amount: string; y: number }[]; markers: { index: number; side: "BUY" | "SELL"; label: string }[] }[];

const percentText = (basisPoints: bigint) => `${basisPoints > 0n ? "+" : basisPoints < 0n ? "-" : ""}${(basisPoints < 0n ? -basisPoints : basisPoints) / 100n}.${((basisPoints < 0n ? -basisPoints : basisPoints) % 100n).toString().padStart(2, "0")}%`;

export function positionChartView(chart: PositionChart, format: Format): PositionChartView {
  return chart.periods.map(period => {
    const points = period.points.map(point => ({ date: point.at, label: format.dateTime(point.at), amount: format.money(toMinor(point.price, period.currency), period.currency), y: Number(point.price) }));
    const times = period.points.map(point => Date.parse(point.at)), first = times[0], last = times.at(-1)!;
    const markers = chart.trades.flatMap(trade => {
      const at = Date.parse(trade.at);
