319	      {account.balance.unconfirmed_rows ? <p className="mt-2 px-2 text-xs text-warning">{account.balance.warnings.at(-1)}.</p> : null}
320	      {suggestion ? <div className="mt-2 px-2"><RenameSuggestion account={{ id: account.id, name: account.name, type: account.type ?? "checking", version: account.version ?? 1, archived_at: account.archived_at ?? null }} suggestion={suggestion} requestId={randomUUID()} /></div> : null}
321	      {!account.archived_at && !synced.has(JSON.stringify([account.name, account.currency_code])) ? <details className="mt-2 px-2 text-sm" open={(account.balance.status === "missing" && active.length === 1) || account.balance.status === "ambiguous"}>
322	        <summary className="cursor-pointer text-xs font-medium text-brand">{account.balance.status === "ambiguous" ? "Review balance" : "Update balance"}</summary>
323	        <div className="mt-3 space-y-3">
324	          <BalanceForm accountId={account.id} name={account.name} currency={account.currency_code} today={today} requestId={randomUUID()}
325	            expectedSnapshotId={latest?.id ?? ""} expectedVersion={latest?.version ?? 0}
326	            placeholder={amount !== null ? formatInputAmount(amount, account.currency_code) : "0.00"}
327	            review={balanceReviewRows(evidence.ledger, account.id, evidence.asOf, timeZone).map(covered => ({ id: covered.id, covered,
328	              label: `${descriptions.get(covered.id) ?? "Recorded posting"} · ${formatMoney(covered.amount_minor, covered.currency_code, locale)}` }))} />
329	          <p className="text-xs text-muted-foreground">Booked balance is what your bank shows as settled, without pending items or any overdraft limit. Earlier balances stay in history.</p>
330	          {manual.length ? <ul className="divide-y divide-border text-xs">{manual.map(snapshot => <li key={snapshot.id} className="flex flex-wrap items-center justify-between gap-2 py-1.5">
331	            <span className={snapshot.undone_at ? "text-muted-foreground line-through" : ""}>{formatMoney(snapshot.amount_minor, snapshot.currency_code, locale)} · as of {calendarDate(snapshot.as_of, timeZone)}{snapshot.boundary_kind === "reviewed_activity" ? " · activity reviewed" : ""}</span>
332	            {snapshot.undone_at ? <span className="text-muted-foreground">Undone</span> : snapshot.id === newestActive?.id && latest ? <SafeForm action={undoBalanceSafely}>
333	              <input type="hidden" name="snapshotId" value={snapshot.id} /><input type="hidden" name="expectedVersion" value={snapshot.version ?? 1} />
334	              <input type="hidden" name="expectedLatestId" value={latest.id} /><input type="hidden" name="expectedLatestVersion" value={latest.version ?? 1} />
335	              <button aria-label={`Undo balance of ${formatMoney(snapshot.amount_minor, snapshot.currency_code, locale)} for ${account.name}`} className="underline">Undo balance</button></SafeForm> : null}
336	          </li>)}</ul> : null}
337	        </div>
338	      </details> : null}
339	    </article>;
340	  }
341	  const scalableCard = scalable ? <ScalableCard key="scalable" setting={<ScalableLiveToggle live={settings.artifact_scalable_data === "live"} />}>
342	      {scalable.portfolio ? <ScalablePortfolioView portfolio={scalable.portfolio as ScalablePortfolio} locale={locale} /> : <p className="text-sm text-muted-foreground">Holdings appear after the first sync.</p>}
343	  </ScalableCard> : null;
344	  const others = active.filter(account => !fedIds.has(account.id));
345	
346	  return <main className="mx-auto w-full max-w-[1400px] space-y-8 px-4 py-6 sm:px-8 lg:py-8">
347	    <header className="space-y-4">
348	      <div className="relative flex flex-wrap items-end justify-between gap-4">
349	        <div className="flex flex-col gap-1"><p className="eyebrow">Money · balances and sources</p><h1 className="page-title">Accounts</h1></div>
350	        <AddAccountPanel>
351	          <SafeForm action={addAccountSafely} className="absolute right-0 z-10 mt-2 grid w-72 max-w-full gap-3 rounded-xl border border-border bg-card p-4 shadow-lg">
352	            <label className="grid gap-1 text-sm">Name<input name="name" className={field} maxLength={120} required /></label>
353	            <div className="flex gap-3">
354	              <label className="grid flex-1 gap-1 text-sm">Type<select name="type" className={field}>{accountTypes.map(type => <option key={type} value={type}>{type[0].toUpperCase() + type.slice(1)}</option>)}</select></label>
355	              <label className="grid gap-1 text-sm">Currency<input name="currency" className={`${field} w-20 uppercase`} defaultValue={workspace.display_currency} pattern="[A-Za-z]{3}" maxLength={3} required /></label>
356	            </div>
357	            <p className="text-xs text-muted-foreground">Currency can’t be changed later.</p>
358	            <button className="min-h-9 rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground hover:opacity-90">Add account</button>
359	            <button type="button" data-close className="min-h-9 rounded-lg px-3 py-1.5 text-sm text-muted-foreground hover:bg-muted">Cancel</button>
360	          </SafeForm>
361	        </AddAccountPanel>
362	      </div>
363	      {totals.size ? <dl className="rounded-xl border border-border bg-card px-5 py-4"><dt className="text-xs text-muted-foreground">Total{counted === active.length ? ` across ${active.length} active ${active.length === 1 ? "account" : "accounts"}` : ""}</dt>
364	        {[...totals].map(([currency, amount]) => <dd key={currency} className="mt-1 font-mono text-2xl font-semibold tabular-nums">{formatMoney(amount, currency, locale)}</dd>)}<dd className="mt-1"><CoverageNote counted={counted} total={active.length} /></dd></dl>
365	        : active.length ? <p className="rounded-xl border border-warning/40 bg-card px-5 py-4 text-sm text-warning">Total unavailable: {active.length} {active.length === 1 ? "account needs" : "accounts need"} a usable balance. <a className="underline" href="#needs-balance">Review {active.length === 1 ? "it" : "them"}</a>.</p> : null}
366	    </header>
367	
368	    <ConnectedArea locale={locale} timeZone={timeZone} result={bank} connect={connect} initial={bankConnections as ConnectionsData} feeds={feeds} hasScalable={Boolean(scalable)} scalable={scalableCard} />
369	
370	    {others.length ? <section id="needs-balance" className="scroll-mt-20 space-y-3" aria-labelledby="other-accounts"><h2 id="other-accounts" className="text-base font-semibold">Imported and entered by hand</h2>
371	      <div className="divide-y divide-border rounded-xl border border-border bg-card">{others.map(account => row(account))}</div></section>
372	      : !active.length ? <p className="rounded-xl border border-border bg-card p-6 text-sm text-muted-foreground">No accounts yet. Use Add account to connect a bank or Scalable, <Link className="underline" href="/import">import a statement</Link> or enter one by hand.</p> : null}
373	
374	    <OwnAccounts identifiers={identifiers ?? []} accounts={active.map(account => ({ id: account.id, name: account.name }))} transfers={transfers}
375	      banked={(bankAccounts ?? []).flatMap(item => item.iban ? [{ iban: item.iban, name: item.account_name }] : [])} />
376	
377	    {archived.length ? <section className="space-y-2 opacity-80" aria-label="Archived accounts"><h2 className="text-sm font-medium text-muted-foreground">Archived accounts ({archived.length})</h2><div className="divide-y divide-border rounded-xl border border-border bg-card">{archived.map(account => row(account))}</div></section> : null}
378	
379	    <Suspense fallback={<div className="h-10" aria-busy="true" />}><AccountHistory accounts={accounts} /></Suspense>
380	  </main>;
381	}
382	
383	async function AccountHistory({ accounts }: { accounts: Resolved[] }) {
384	  const { supabase, workspace: { id, locale, timezone: timeZone } } = await requireWorkspace();
385	  const { data: history, error: historyError } = await supabase.from("money_metadata_events").select("id,entity_type,entity_id,before,after,created_at,undone_at,undo_of").eq("workspace_id", id).order("created_at", { ascending: false }).limit(30);
386	  if (historyError) throw new Error("Could not load account and saved view history");
387	  const viewIds = [...new Set((history ?? []).filter(event => event.entity_type === "transaction_view" && !event.undone_at && !event.undo_of).map(event => event.entity_id))];
388	  const { data: views, error: viewsError } = viewIds.length ? await supabase.from("transaction_views").select("id,version").eq("workspace_id", id).in("id", viewIds) : { data: [], error: null };
389	  if (viewsError) throw new Error("Could not load account and saved view history");
390	  const versions = new Map<string, number>([...accounts.map(account => [account.id, account.version ?? 1] as const), ...(views ?? []).map(view => [view.id, view.version] as const)]);
391	  const events = (history ?? []) as MetaEvent[];
392	  const latestVersion = new Map<string, number>();
393	  for (const event of events) if (!event.undone_at && !event.undo_of)
394	    latestVersion.set(event.entity_id, Math.max(latestVersion.get(event.entity_id) ?? 0, Number(event.after?.version ?? 0)));
395	  const canUndo = (event: MetaEvent) => !event.undone_at && !event.undo_of && versions.has(event.entity_id) && Number(event.after?.version ?? 0) >= (latestVersion.get(event.entity_id) ?? 0);
396	  const when = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "medium", timeStyle: "short" });
397	  return events.length ? <section><h2 className="text-sm font-medium text-muted-foreground">Account and saved view history</h2>
398	      <ul className="mt-2 divide-y divide-border text-sm">{events.map(event => <li key={event.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
399	        <span>{describeEvent(event)} <span className="text-muted-foreground">· {when.format(new Date(event.created_at))}{event.undone_at ? " · Undone" : event.undo_of ? " · Restored by undo" : ""}</span></span>
400	        {canUndo(event) ? <SafeForm action={undoMoneyMetadataSafely}><input type="hidden" name="eventId" value={event.id} /><input type="hidden" name="version" value={versions.get(event.entity_id)} /><input type="hidden" name="requestId" value={randomUUID()} /><button aria-label={`Undo: ${describeEvent(event)}`} className={field}>Undo</button></SafeForm> : null}
401	      </li>)}</ul>
402	    </section> : null;
403	}
