import Link from "next/link";
import { FocusOnOpen } from "@/components/focus-on-open";
import { ScalablePositionChart } from "@/components/scalable-position-chart";
import { ScalablePositionNews } from "@/components/scalable-position-news";
import { requireWorkspace } from "@/lib/auth";
import { displayFormat } from "@/lib/display-format";
import type { WealthItem } from "@/lib/finance/wealth";
import { positionChartView } from "@/lib/scalable/chart-view";
import { loadPositionChart } from "@/lib/scalable/charts";

const shell = "fixed inset-y-0 right-0 z-50 w-full max-w-lg overflow-y-auto border-l border-border bg-card shadow-2xl";

export async function PositionDrawer({ isin, item }: { isin: string; item: WealthItem | null }) {
  const { supabase, workspace } = await requireWorkspace();
  const close = <Link href="/money/wealth" scroll={false} className="inline-flex min-h-11 items-center text-sm text-muted-foreground underline hover:text-foreground">Close</Link>;
  if (!item) return <aside aria-label="Position details" className={`${shell} p-6`}>{close}<p role="alert" className="mt-4 text-sm">This position isn’t available.</p></aside>;
  const { money, dateTime } = displayFormat(workspace.locale, workspace.timezone);
  const views = positionChartView(await loadPositionChart(supabase, workspace.id, isin), { money, dateTime });
  const gain = item.cost_basis_minor === null ? null : BigInt(item.amount_minor) - BigInt(item.cost_basis_minor);
  return <aside aria-label="Position details" className={shell}>
    <FocusOnOpen label={`Details for ${item.name}`} />
    <div className="sticky top-0 z-10 flex items-center justify-between border-b border-border bg-card px-6 py-1">{close}<span className="font-mono text-[11px] text-subtle">{isin}</span></div>
    <div className="space-y-6 p-6">
      <header>
        <h2 className="font-display text-[28px] font-semibold leading-tight tracking-tight">{item.name}</h2>
        <p className="mt-1 font-mono text-[26px] tabular-nums">{money(item.amount_minor, item.currency_code)}</p>
        <p className="mt-1 text-xs text-muted-foreground">{item.quantity_text} shares{gain === null ? "" : ` · ${gain > 0n ? "+" : ""}${money(gain, item.currency_code)} since bought`}</p>
      </header>
      <ScalablePositionChart name={item.name} views={views} />
      <ScalablePositionNews isin={isin} />
    </div>
  </aside>;
}
import { CoverageNote } from "@/components/coverage-note";
import { ScalableInvestments } from "@/components/scalable-investments";
import type { ScalablePortfolio } from "@/lib/scalable/portfolio";
import { SafeForm } from "@/components/safe-form";
import Link from "next/link";
import { redirect } from "next/navigation";
import type { SupabaseClient } from "@supabase/supabase-js";
import { requireWorkspace } from "@/lib/auth";
import { calendarDate } from "@/lib/finance/calendar";
import { carriedDebtPayments, currentOn, loadWealthItems, type WealthItem } from "@/lib/finance/wealth";
import { loadBalanceEvidence } from "@/lib/finance/balances";
import { describeOutdated, formatMoney as formatCurrency } from "@/lib/finance/format";
import { NetWorthChart } from "@/components/net-worth-chart";
import { WealthForm } from "./form";
import { removeWealthItemSafely, undoWealthEventSafely } from "./actions";
import { NetWorthProblems } from "./net-worth-problems";
import { loadImportStates, loadRepaymentLinks, netWorthFindings } from "@/lib/finance/net-worth-checks";
import { dayRange, firstRealValue, loadWealthEvents, monthEnds, netWorth, netWorthSeries } from "@/lib/finance/net-worth";
import { describeMonthSplit, loadNetWorthEvidence, netWorthModel } from "@/lib/finance/net-worth-source";
import { transitOn } from "@/lib/finance/transit";
import { chartedIsins } from "@/lib/scalable/charts";
import { scalableItemId } from "@/lib/scalable/portfolio";
import { PositionDrawer } from "./position-drawer";

export const metadata = { title: "Wealth" };

const MONTHS = 12;
const HISTORY = 50;
const sections = [["holding", "Investments"], ["asset", "Assets"], ["debt", "Debts"]] as const;

function sum(items: WealthItem[]) {
  const totals = new Map<string, bigint>();
  for (const item of items) if (!item.linked_account_id) totals.set(item.currency_code, (totals.get(item.currency_code) ?? 0n) + BigInt(item.amount_minor));
  return totals;
}

export default async function WealthPage({ searchParams }: { searchParams?: Promise<{ removed?: string; history?: string; position?: string }> } = {}) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/setup"); }
  const { supabase, workspace } = context;
  const params = (await searchParams) ?? {};
  const db = supabase as SupabaseClient;
  const formatMoney = (amount: Parameters<typeof formatCurrency>[0], currency: string) => formatCurrency(amount, currency, workspace.locale);
  const today = calendarDate(new Date(), workspace.timezone);
  const itemsPromise = loadWealthItems(supabase, workspace.id, true), eventsPromise = loadWealthEvents(db, workspace.id), balancesPromise = loadBalanceEvidence(db, workspace.id, new Date().toISOString());
  const [items, accounts, assumptions, pending, events, scalable, netWorthEvidence, imports, repayments, charted] = await Promise.all([
    itemsPromise,
    supabase.from("accounts").select("id, name, type, currency_code, archived_at").eq("workspace_id", workspace.id).order("name"),
    supabase.from("financial_assumptions").select("id, name, amount_minor::text, currency_code, starts_on").eq("workspace_id", workspace.id).eq("confirmed", true).eq("enabled", true).eq("cadence", "monthly").is("removed_at", null).order("name"),
    supabase.from("transactions").select("id, description, amount_minor::text, currency_code, posted_on").eq("workspace_id", workspace.id).eq("status", "pending").order("posted_on", { ascending: false }).limit(100),
    eventsPromise,
    supabase.from("scalable_connections").select("status, last_synced_at, portfolio, history_status").eq("workspace_id", workspace.id).in("status", ["active", "expired", "error"])
      .not("portfolio", "is", null).order("created_at", { ascending: false }).limit(1).maybeSingle(),
    loadNetWorthEvidence(db, workspace, { balances: balancesPromise, items: itemsPromise, events: eventsPromise }),
    loadImportStates(db, workspace.id),
    loadRepaymentLinks(db, workspace.id),
    chartedIsins(db, workspace.id),
  ]);
  for (const result of [accounts, assumptions, pending]) if (result.error) throw result.error;
  const active = items.filter(item => !item.removed_at);
  const choices = { accounts: accounts.data ?? [], assumptions: (assumptions.data ?? []).map(item => ({ id: item.id, currency_code: item.currency_code, label: `${item.name} · ${formatMoney(item.amount_minor, item.currency_code)} · ${item.starts_on}` })),
    pending: (pending.data ?? []).map(item => ({ id: item.id, currency_code: item.currency_code, label: `${item.description} · ${formatMoney(item.amount_minor, item.currency_code)} · ${item.posted_on}` })), today, currency: workspace.display_currency, locale: workspace.locale };
  const itemById = new Map(items.map(item => [item.id, item]));

  const evidence = netWorthEvidence.balances, calculatedHistory = netWorthEvidence.scalable;
  const worth = netWorthModel(netWorthEvidence);
  const { calculated, valuations: allValuations, accounts: resolved, dated: valuations, now } = worth;
  const series = worth.points(monthEnds(today, MONTHS));
  const monthWords = describeMonthSplit(worth.monthSplit(workspace.display_currency), minor => formatMoney(minor, workspace.display_currency));
  const unbalanced = resolved.filter(account => account.balance.amount_minor === null).length;
  const totals = netWorth(now);
  const currencies = [...totals.keys()].sort((a, b) => Number(b === workspace.display_currency) - Number(a === workspace.display_currency) || a.localeCompare(b));
  const chartPoints = (currency: string) => series.flatMap(point => { const value = netWorth(point).get(currency); return value === undefined || !point.known ? [] : [{ date: point.date, value, uncertain: point.uncertain.join(". ") || undefined }]; });
  const returned = worth.windows.filter(window => window.kind === "returned");
  const withReturns = (date: string, value: bigint, currency: string) => value + (transitOn(returned, date).get(currency) ?? 0n);
  const history = params.history === "all" ? events : events.slice(0, HISTORY);
  const portfolio = (scalable.data?.portfolio ?? null) as ScalablePortfolio | null;
  const scalableIds = new Set(portfolio?.itemIds ?? []), knownIds = new Set([...(portfolio?.knownItemIds ?? []), ...scalableIds]);
  const positionLinks = Object.fromEntries([...charted].map(isin => [scalableItemId(workspace.id, `isin:${isin}`), isin]));
  const openIsin = params.position && positionLinks[scalableItemId(workspace.id, `isin:${params.position}`)] ? params.position : null;
  const scalableHistory = (() => {
    if (!portfolio) return [];
    const valuations = allValuations.filter(row => knownIds.has(row.item_id));
    const from = valuations.reduce((min, row) => row.as_of < min ? row.as_of : min, today);
    return netWorthSeries({ dates: dayRange(from, today), timeZone: workspace.timezone, accountIds: new Set(), snapshots: [], valuations })
      .flatMap(point => { const value = netWorth(point).get(portfolio.currency); return value === undefined ? [] : [{ date: point.date, value: withReturns(point.date, value, portfolio.currency) }]; });
  })();
  const findings = netWorthFindings({ accounts: resolved, snapshots: evidence.snapshots, ledger: evidence.ledger, timeZone: workspace.timezone, locale: workspace.locale, portfolio, imports, repayments,
    lastCalculated: calculated.rows.at(-1) ?? null, firstReal: firstRealValue(allValuations, calculatedHistory.knownIds, calculated.before, portfolio?.currency ?? "EUR"), movedOnBoundaryMinor: worth.movedOnBoundaryMinor });
  const scalableCalculated = portfolio && calculated.before ? calculated.rows.filter(row => row.on_date < calculated.before! && row.currency_code === portfolio.currency) : [];

  return <main className="mx-auto w-full max-w-[1400px] space-y-8 px-4 py-6 sm:px-8 lg:py-8">
    <header className="flex flex-col gap-1"><p className="eyebrow">Investments · assets · debts</p><h1 className="page-title">Wealth</h1></header>

    <section aria-label="Net worth" className="space-y-4">
      {currencies.map(currency => { const recorded = chartPoints(currency); const values = recorded.map(point => point.value); const low = values.reduce((a, b) => b < a ? b : a, values[0]), high = values.reduce((a, b) => b > a ? b : a, values[0]); return <div key={currency} className="rounded-xl border border-border bg-card p-6">
        <h2 className="text-sm text-muted-foreground">Net worth ({currency})</h2>
        <p className="mt-1 break-words font-mono text-3xl font-semibold tracking-tight tabular-nums sm:text-4xl">{formatMoney(totals.get(currency) ?? 0n, currency)}</p>
        {currency === workspace.display_currency && monthWords && <p className="mt-1 font-mono text-xs text-muted-foreground">This month: {monthWords}</p>}
        <div className="mt-1"><CoverageNote counted={resolved.length - unbalanced} total={resolved.length} /></div>
        <dl className="mt-5 grid gap-4 sm:grid-cols-3 border-t border-border pt-4 text-sm">
          {([["Accounts", now.accounts], ["Investments & assets", now.assets], ["Debts", now.debts]] as const).map(([label, map]) => <div key={label}>
            <dt className="text-xs text-muted-foreground">{label}</dt><dd className="mt-0.5 break-words font-mono tabular-nums">{formatMoney(map.get(currency) ?? 0n, currency)}</dd></div>)}
        </dl>
        <div className="mt-5"><NetWorthChart label={`Recorded net worth in ${currency} at each month end`}
          points={recorded.map(point => ({ date: point.date, label: point.date === today ? "Today" : point.date, amount: formatMoney(point.value, currency), y: Number(point.value), uncertain: point.uncertain }))} /></div>
        <p className="mt-1 flex justify-between text-xs text-muted-foreground"><span>{recorded[0].date}</span><span>Today</span></p>
        <p className="mt-1 text-xs text-muted-foreground">Lowest {formatMoney(low, currency)} · highest {formatMoney(high, currency)}</p>
        <details className="mt-2"><summary className="min-h-11 cursor-pointer content-center text-sm underline">Net worth by month</summary>
          <table className="mt-2 w-full text-sm"><caption className="sr-only">Recorded net worth in {currency} at each month end</caption><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th scope="col" className="py-1.5 font-medium">Date</th><th scope="col" className="py-1.5 text-right font-medium">Net worth</th></tr></thead>
            <tbody>{series.map(point => { const value = netWorth(point).get(currency); return <tr key={point.date} className="border-b border-border last:border-0"><th scope="row" className="py-1.5 text-left font-normal">{point.date === today ? "Today" : point.date}</th><td className="py-1.5 text-right font-mono tabular-nums">{value === undefined || !point.known ? "Nothing recorded" : formatMoney(value, currency)}{point.uncertain.length > 0 && <span className="block font-sans text-xs text-warning">Not proven: {point.uncertain.join(". ")}</span>}</td></tr>; })}</tbody></table>
        </details>
      </div>; })}
      {valuations.outdated.length > 0 && <p className="text-xs text-muted-foreground">{describeOutdated(valuations.outdated)}</p>}
      {unbalanced > 0 && <p className="text-sm">{unbalanced} account{unbalanced === 1 ? " has" : "s have"} no usable balance and {unbalanced === 1 ? "is" : "are"} left out. <Link href="/money/accounts" className="font-medium text-brand underline">Review account balances</Link></p>}
      {!currencies.length && !active.length && <div className="rounded-xl border border-border bg-card p-6 text-sm"><p className="font-medium">Add your first item</p><p className="mt-1 text-muted-foreground">Net worth is your accounts plus investments and assets, minus debts. Start with one below.</p></div>}
      {!currencies.length && active.length > 0 && <p className="rounded-xl border border-border bg-card p-6 text-sm text-muted-foreground">No recorded balances or valuations count today yet.</p>}
      <NetWorthProblems findings={findings} unresolved={worth.unresolved} locale={workspace.locale} />
    </section>

    {portfolio && <ScalableInvestments portfolio={portfolio} positions={active.filter(item => scalableIds.has(item.id) && item.kind === "holding").sort((a, b) => Number(BigInt(b.amount_minor) - BigInt(a.amount_minor)))}
      history={[...scalableCalculated.map(row => ({ date: row.on_date, value: withReturns(row.on_date, BigInt(row.total_minor), row.currency_code) })), ...scalableHistory]} calculatedBefore={scalableCalculated.length ? calculated.before : null}
      historyFailed={scalable.data?.history_status === "failed"} syncedAt={scalable.data?.last_synced_at ?? null} active={scalable.data?.status === "active"} locale={workspace.locale} timeZone={workspace.timezone} positionLinks={positionLinks} />}

    <section aria-label="Add wealth" className="flex flex-wrap gap-2">{sections.map(([kind, title]) => <details key={kind} className="group rounded-lg border border-border bg-card open:basis-full open:p-5"><summary className="cursor-pointer px-3 py-1.5 text-sm font-medium group-open:p-0">Add {kind === "holding" ? "investment" : kind}<span className="sr-only"> ({title})</span></summary><WealthForm kind={kind} {...choices} /></details>)}</section>

    {sections.map(([kind, title]) => {
      const rows = active.filter(item => item.kind === kind && !scalableIds.has(item.id));
      if (!rows.length) return null;
      return <section key={kind} aria-label={title} className="space-y-3">
        <div className="flex flex-wrap items-baseline justify-between gap-2"><h2 className="text-sm font-medium">{title} <span className="font-normal text-muted-foreground">{rows.length}</span></h2>
          <p className="font-mono text-sm text-muted-foreground tabular-nums">{[...sum(rows.filter(item => item.as_of <= today))].map(([currency, amount]) => formatMoney(amount, currency)).join(" · ")}</p></div>
        <div className="divide-y divide-border rounded-xl border border-border bg-card">{rows.map(item => {
          const payments = (() => { try { return item.kind === "debt" && item.next_payment_on && BigInt(item.monthly_payment_minor ?? "0") > 0n ? carriedDebtPayments({ principalMinor: BigInt(item.amount_minor), annualRate: item.annual_rate_text!, monthlyPaymentMinor: BigInt(item.monthly_payment_minor!), nextPaymentOn: item.next_payment_on, asOf: item.as_of }, today, 365) : []; } catch { return null; } })();
          return <article key={item.id} id={`item-${item.id}`} className="scroll-mt-24 space-y-2 px-5 py-4">
            <div className="flex flex-wrap items-baseline justify-between gap-2"><h3 className="font-medium">{item.name}</h3>
              <p className="font-mono font-semibold tabular-nums">{formatMoney(item.amount_minor, item.currency_code)}</p></div>
            <p className="text-xs text-muted-foreground">As of {item.as_of}{item.kind === "holding" ? ` · ${item.quantity_text} × ${item.currency_code} ${item.unit_price_text}` : ""}{item.kind === "debt" ? ` · ${item.annual_rate_text}% a year · ${formatMoney(item.monthly_payment_minor ?? "0", item.currency_code)}/month` : ""}{item.linked_account_id ? " · Inside an account balance" : item.as_of > today ? " · Dated in the future, not in net worth" : currentOn(item, today) ? "" : " · Not from today, last known value"}</p>
            {item.cost_basis_minor !== null && (() => { const gain = BigInt(item.amount_minor) - BigInt(item.cost_basis_minor); const cost = BigInt(item.cost_basis_minor);
              return <p className={`text-xs ${gain > 0n ? "text-success" : gain < 0n ? "text-danger" : "text-muted-foreground"}`}>{gain > 0n ? "+" : ""}{formatMoney(gain, item.currency_code)}{cost > 0n ? ` (${gain > 0n ? "+" : ""}${(Number(gain * 10000n / cost) / 100).toFixed(1)}%)` : ""} since bought for {formatMoney(cost, item.currency_code)}</p>; })()}
            {item.kind === "debt" && (payments === null ? <p className="text-xs text-warning">Update the next repayment date and principal to project payments.</p> : payments.length > 0 && <ul className="space-y-0.5 text-xs text-muted-foreground">{payments.slice(0, 3).map(payment => <li key={payment.date}>{payment.date}: {formatMoney(payment.paymentMinor, item.currency_code)} payment, {formatMoney(payment.interestMinor, item.currency_code)} assumed interest, {formatMoney(payment.remainingMinor, item.currency_code)} left</li>)}</ul>)}
            <div className="flex flex-wrap items-start gap-4">
              <details className="min-w-0 flex-1"><summary className="cursor-pointer text-sm text-muted-foreground hover:text-foreground">Edit valuation and details</summary><WealthForm kind={item.kind} item={item} {...choices} /></details>
              <SafeForm action={removeWealthItemSafely}><input type="hidden" name="id" value={item.id} /><input type="hidden" name="version" value={item.version} /><input type="hidden" name="requestId" value={crypto.randomUUID()} /><button aria-label={`Remove ${item.name} (keep history)`} className="min-h-11 text-sm text-muted-foreground hover:text-foreground">Remove</button></SafeForm>
            </div>
          </article>;
        })}</div>
      </section>;
    })}
    {params.removed === "1" && <p role="status" className="text-sm">Removed from your net worth. Its history is kept, and Undo below brings it back.</p>}
    <details id="wealth-history" open={params.removed === "1" || params.history === "all"} className="scroll-mt-24 rounded-xl border border-border bg-card px-5 py-4"><summary className="cursor-pointer text-sm font-medium">Wealth source history and undo</summary><ul className="mt-3 divide-y divide-border">{history.map(event => {
      const { after, before } = event; const current = itemById.get(event.item_id);
      return <li key={event.id} className="flex flex-wrap items-center justify-between gap-3 py-2 text-sm"><span><span className="font-medium">{after.name}</span> <span className="font-mono tabular-nums">{before ? formatMoney(before.amount_minor, before.currency_code) : "New"} → {formatMoney(after.amount_minor, after.currency_code)}</span>{after.removed_at ? " · Removed" : ""}
        <span className="block text-xs text-muted-foreground">Valued {after.as_of} · saved {new Date(event.created_at).toLocaleString(workspace.locale, { timeZone: workspace.timezone })}{event.undone_at ? " · Undone" : ""}</span></span>
        {!event.undone_at && current && <SafeForm action={undoWealthEventSafely}><input type="hidden" name="eventId" value={event.id} /><input type="hidden" name="version" value={current.version} /><button aria-label={`Undo ${after.name} change`} className="min-h-11 text-sm text-muted-foreground hover:text-foreground">Undo</button></SafeForm>}</li>;
    })}</ul>{history.length < events.length && <a href="/money/wealth?history=all#wealth-history" className="mt-2 inline-flex min-h-11 items-center text-sm font-medium text-brand underline">Show all {events.length} changes</a>}{!events.length && <p className="mt-2 text-sm text-muted-foreground">Every add, edit and removal appears here with undo.</p>}</details>
    {params.position ? <PositionDrawer key={params.position} isin={params.position} item={openIsin ? items.find(item => item.id === scalableItemId(workspace.id, `isin:${openIsin}`) && !item.removed_at) ?? null : null} /> : null}
  </main>;
}
import { Suspense } from "react";
import Link from "next/link";
import { SafeForm } from "@/components/safe-form";
import { CoverageNote } from "@/components/coverage-note";
import { randomUUID } from "node:crypto";
import { requireWorkspace } from "@/lib/auth";
import { balanceReviewRows, loadBalanceEvidence, resolveBalances, type BalanceSnapshot } from "@/lib/finance/balances";
import { calendarDate } from "@/lib/finance/calendar";
import { closingTargets } from "@/lib/finance/account-closing";
import { formatInputAmount, formatMoney } from "@/lib/finance/format";
import { addAccountSafely, undoBalanceSafely, undoMoneyMetadataSafely } from "./actions";
import { AddAccountPanel } from "./add-account-panel";
import { AccountForm, BalanceForm, RenameSuggestion } from "./account-form";
import { accountTypes, suggestAccountName } from "./naming";
import { balanceTrend, shownBalance, trendSummary } from "./history";
import { Sparkline } from "./sparkline";
import { OwnAccounts } from "./own-accounts";
import { ScalablePortfolioView } from "@/components/scalable-portfolio";
import { ConnectedArea, type ConnectionsData } from "@/components/connected-banks";
import { loadBankConnections } from "@/lib/bank/connections";
import { ScalableCard } from "@/components/scalable-connection";
import { maskAccountNumber } from "@/lib/import/csv";
import { ScalableLiveToggle } from "./scalable-live-toggle";
import type { ScalablePortfolio } from "@/lib/scalable/portfolio";

export const metadata = { title: "Accounts" };

const field = "min-h-9 rounded-lg border border-border bg-card px-2.5 py-1.5 text-sm";
const TREND_DAYS = 90;
type Resolved = ReturnType<typeof resolveBalances>[number];
type MetaEvent = { id: string; entity_type: string; entity_id: string; before: Record<string, unknown> | null; after: Record<string, unknown> | null; created_at: string; undone_at: string | null; undo_of: string | null };

function describeEvent(event: MetaEvent) {
  const before = event.before ?? {}, after = event.after ?? {};
  const changes = [
    before.name !== after.name && before.name && after.name ? `renamed “${before.name}” → “${after.name}”` : null,
    before.type !== after.type && before.type && after.type ? `type ${before.type} → ${after.type}` : null,
    Boolean(before.archived_at) !== Boolean(after.archived_at) ? (after.archived_at ? "archived" : "restored") : null,
    Boolean(before.removed_at) !== Boolean(after.removed_at) ? (after.removed_at ? "removed" : "restored") : null,
  ].filter(Boolean);
  return `${event.entity_type === "account" ? "Account" : "Saved view"} ${String(after.name ?? before.name ?? "")}${changes.length ? `: ${changes.join(", ")}` : ""}`;
}

export default async function AccountsPage({ searchParams }: { searchParams?: Promise<{ transfers?: string; saved?: string; bank?: string; connect?: string }> } = {}) {
  const { transfers, saved, bank, connect } = (await searchParams) ?? {};
  const { supabase, workspace, settings } = await requireWorkspace();
  const [evidence, { data: bankAccounts, error: bankError }, { data: identifiers, error: identifierError }, { data: scalable }, { data: fileSources, error: sourceError }, bankConnections] = await Promise.all([
    loadBalanceEvidence(supabase, workspace.id, new Date().toISOString()),
    supabase.from("bank_connection_accounts").select("connection_id,account_name,currency_code,iban,last_booked_on,bank_connections(status)").eq("workspace_id", workspace.id),
    supabase.from("own_account_identifiers").select("id,account_id,iban,label").eq("workspace_id", workspace.id).order("created_at"),
    supabase.from("scalable_connections").select("portfolio").eq("workspace_id", workspace.id).in("status", ["active", "expired", "error"])
      .order("created_at", { ascending: false }).limit(1).maybeSingle(),
    supabase.from("data_sources").select("account_id").eq("workspace_id", workspace.id).eq("kind", "file").not("account_id", "is", null),
    loadBankConnections(supabase, workspace.id),
  ]);
  if (bankError || identifierError || sourceError) throw new Error("Could not load account identifiers");
  const synced = new Set((bankAccounts ?? []).map(connected => JSON.stringify([connected.account_name, connected.currency_code])));
  const stillFed = new Set((bankAccounts ?? []).filter(connected => connected.bank_connections?.status !== "revoked").map(connected => JSON.stringify([connected.account_name, connected.currency_code])));
  const { timezone: timeZone, locale } = workspace;
  const today = calendarDate(evidence.asOf, timeZone);
  const trendFrom = calendarDate(new Date(Date.parse(evidence.asOf) - TREND_DAYS * 86400000), timeZone);
  const accounts = resolveBalances(evidence.accounts, evidence.snapshots, evidence.ledger, evidence.asOf, timeZone)
    .sort((a, b) => a.name.localeCompare(b.name, locale));
  const active = accounts.filter(account => !account.archived_at), archived = accounts.filter(account => account.archived_at);
  const descriptions = new Map(evidence.ledger.map(row => [row.id, row.description]));
  const snapshotsByAccount = new Map<string, BalanceSnapshot[]>();
  for (const snapshot of evidence.snapshots) snapshotsByAccount.set(snapshot.account_id, [...(snapshotsByAccount.get(snapshot.account_id) ?? []), snapshot]);

  const totals = new Map<string, bigint>();
  let counted = 0;
  for (const account of active) {
    const { amount } = shownBalance(account.balance);
    if (amount === null || account.balance.status === "ambiguous") continue;
    counted += 1;
    totals.set(account.currency_code, (totals.get(account.currency_code) ?? 0n) + BigInt(amount));
  }

  const key = (name: string, currency: string) => JSON.stringify([name, currency]);
  const live = (bankAccounts ?? []).filter(connected => connected.bank_connections?.status !== "revoked");
  const fedIds = new Set<string>();
  const feeds = Object.fromEntries([...new Set(live.map(connected => connected.connection_id))].map(connectionId => [connectionId,
    <ul key={connectionId} aria-label="Accounts this bank feeds" className="-mx-5 divide-y divide-border border-t border-border">{live.filter(connected => connected.connection_id === connectionId).map(connected => {
      const account = accounts.find(item => key(item.name, item.currency_code) === key(connected.account_name, connected.currency_code));
      if (account) fedIds.add(account.id);
      const detail = `${connected.iban ? `${maskAccountNumber(connected.iban)} · ` : ""}${connected.last_booked_on ? `synced through ${connected.last_booked_on}` : "not synced yet"}`;
      return <li key={key(connected.account_name, connected.currency_code)}>{account ? row(account, detail)
        : <p className="flex justify-between gap-3 px-5 py-3 text-sm"><span className="truncate">{connected.account_name}</span><span className="shrink-0 text-muted-foreground">{connected.currency_code} · {detail}</span></p>}</li>;
    })}</ul>]));
  const imported = new Set([...(fileSources ?? []).map(source => source.account_id), ...evidence.snapshots.filter(snapshot => snapshot.provenance === "import").map(snapshot => snapshot.account_id)]);
  const sourceOf = (account: Resolved) => synced.has(key(account.name, account.currency_code)) ? "From a disconnected bank" : imported.has(account.id) ? "Imported file" : "Entered by hand";

  function row(account: Resolved, source = sourceOf(account)) {
    const { amount, label } = shownBalance(account.balance);
    const snapshots = snapshotsByAccount.get(account.id) ?? [];
    const trend = balanceTrend(snapshots, account.id, account.currency_code, timeZone, trendFrom, amount !== null && account.balance.status !== "ambiguous" ? { date: today, value: BigInt(amount) } : undefined);
    const ordered = [...snapshots].sort((a, b) => Date.parse(b.created_at ?? b.as_of) - Date.parse(a.created_at ?? a.as_of) || (b.id ?? "").localeCompare(a.id ?? ""));
    const latest = ordered[0];
    const newestActive = ordered.find(snapshot => !snapshot.undone_at);
    const manual = ordered.filter((snapshot): snapshot is BalanceSnapshot & { id: string } => Boolean(snapshot.actor_id && snapshot.id)).slice(0, 5);
    const suggestion = suggestAccountName(account.name);
    const asOf = account.balance.as_of ? calendarDate(account.balance.as_of, timeZone) : null;
    return <article key={account.id} id={`account-${account.id}`} aria-label={account.name} className="scroll-mt-24 px-4 py-4 sm:px-5">
      {saved === `balance:${account.id}` || saved === `account:${account.id}` ? <p role="status" className="mb-2 px-2 text-sm text-success">{saved.startsWith("balance") ? `Balance saved for ${account.name}.` : `${account.name} saved.`}</p> : null}
      <div className="flex flex-wrap items-start gap-x-6 gap-y-2">
        <div className="min-w-0 flex-1 basis-80">
          <AccountForm key={`${account.id}:${account.version}`} moneyLeft={account.balance.amount_minor !== null && BigInt(account.balance.amount_minor) !== 0n ? formatMoney(account.balance.amount_minor, account.currency_code, locale) : null} targets={closingTargets(account, accounts).map(({ id, name, type, currency_code }) => ({ id, name, type, bankSynced: stillFed.has(JSON.stringify([name, currency_code])) }))} account={{ id: account.id, name: account.name, type: account.type ?? "checking", version: account.version ?? 1, archived_at: account.archived_at ?? null }} requestId={randomUUID()} />
          <p className="mt-1 flex flex-wrap items-center gap-x-3 px-2 text-xs text-muted-foreground">
            <span>{account.currency_code}</span>
            <span>{source}</span>
            {account.archived_at ? <span>Archived</span> : null}
            <Link aria-label={`Transactions in ${account.name}`} className="hover:text-foreground hover:underline" href={`/money/transactions?account=${account.id}`}>Transactions</Link>
          </p>
        </div>
        <div className="flex items-center gap-4 max-sm:w-full max-sm:justify-between max-sm:px-2">
          <Sparkline points={trend} label={`${account.name} recorded balance, last ${TREND_DAYS} days`} />
          <div className="min-w-36 text-right">
            <p className="font-mono text-base font-semibold tabular-nums">{amount === null ? "—" : formatMoney(amount, account.currency_code, locale)}</p>
            <p className={`text-xs ${account.balance.status === "missing" || account.balance.status === "ambiguous" ? "text-warning" : "text-muted-foreground"}`}>
              {account.balance.status === "ambiguous" ? `${label} · not in total` : `${label}${asOf ? ` · as of ${asOf}` : ""}`}</p>
          </div>
        </div>
      </div>
      {trend.length > 1 ? <details className="mt-2 px-2 text-xs text-muted-foreground"><summary className="cursor-pointer hover:text-foreground">{trendSummary(trend, value => formatMoney(value, account.currency_code, locale))}</summary><ul className="mt-1 space-y-0.5">{trend.map(point => <li key={point.date} className="font-mono">{point.date} · {formatMoney(point.value, account.currency_code, locale)}</li>)}</ul><p className="mt-1">Only the balances recorded on these dates, not one for every day.</p></details> : null}
      {account.balance.status === "ambiguous" ? <div className="mt-2 px-2 text-xs"><p className="text-warning">Moneo can’t tell whether activity on that date came before or after this balance, so it’s left out of the total. Enter the balance your bank shows now to settle it.</p><details className="mt-1 text-muted-foreground"><summary className="cursor-pointer hover:text-foreground">Why</summary><p className="mt-1">{account.balance.warnings.join(" ")}</p></details></div> : null}
      {account.balance.status === "stale" ? <p className="mt-2 px-2 text-xs text-muted-foreground">Last recorded balance plus later activity; update it to confirm.</p> : null}
      {account.balance.conflicts.length > 0 && <div className="mt-2 px-2 text-xs text-warning"><p>Two balances disagree for this date. Moneo uses the most recently recorded one{account.balance.snapshot_amount_minor !== null ? `, ${formatMoney(account.balance.snapshot_amount_minor, account.balance.snapshot_currency_code ?? account.currency_code, locale)}` : ""}. The other said {account.balance.conflicts.map(other => formatMoney(other.amount_minor, other.currency_code, locale)).join(", ")}.</p></div>}
      {account.balance.unconfirmed_rows ? <p className="mt-2 px-2 text-xs text-warning">{account.balance.warnings.at(-1)}.</p> : null}
      {suggestion ? <div className="mt-2 px-2"><RenameSuggestion account={{ id: account.id, name: account.name, type: account.type ?? "checking", version: account.version ?? 1, archived_at: account.archived_at ?? null }} suggestion={suggestion} requestId={randomUUID()} /></div> : null}
      {!account.archived_at && !synced.has(JSON.stringify([account.name, account.currency_code])) ? <details className="mt-2 px-2 text-sm" open={(account.balance.status === "missing" && active.length === 1) || account.balance.status === "ambiguous"}>
        <summary className="cursor-pointer text-xs font-medium text-brand">{account.balance.status === "ambiguous" ? "Review balance" : "Update balance"}</summary>
        <div className="mt-3 space-y-3">
          <BalanceForm accountId={account.id} name={account.name} currency={account.currency_code} today={today} requestId={randomUUID()}
            expectedSnapshotId={latest?.id ?? ""} expectedVersion={latest?.version ?? 0}
            placeholder={amount !== null ? formatInputAmount(amount, account.currency_code) : "0.00"}
            review={balanceReviewRows(evidence.ledger, account.id, evidence.asOf, timeZone).map(covered => ({ id: covered.id, covered,
              label: `${descriptions.get(covered.id) ?? "Recorded posting"} · ${formatMoney(covered.amount_minor, covered.currency_code, locale)}` }))} />
          <p className="text-xs text-muted-foreground">Booked balance is what your bank shows as settled, without pending items or any overdraft limit. Earlier balances stay in history.</p>
          {manual.length ? <ul className="divide-y divide-border text-xs">{manual.map(snapshot => <li key={snapshot.id} className="flex flex-wrap items-center justify-between gap-2 py-1.5">
            <span className={snapshot.undone_at ? "text-muted-foreground line-through" : ""}>{formatMoney(snapshot.amount_minor, snapshot.currency_code, locale)} · as of {calendarDate(snapshot.as_of, timeZone)}{snapshot.boundary_kind === "reviewed_activity" ? " · activity reviewed" : ""}</span>
            {snapshot.undone_at ? <span className="text-muted-foreground">Undone</span> : snapshot.id === newestActive?.id && latest ? <SafeForm action={undoBalanceSafely}>
              <input type="hidden" name="snapshotId" value={snapshot.id} /><input type="hidden" name="expectedVersion" value={snapshot.version ?? 1} />
              <input type="hidden" name="expectedLatestId" value={latest.id} /><input type="hidden" name="expectedLatestVersion" value={latest.version ?? 1} />
              <button aria-label={`Undo balance of ${formatMoney(snapshot.amount_minor, snapshot.currency_code, locale)} for ${account.name}`} className="underline">Undo balance</button></SafeForm> : null}
          </li>)}</ul> : null}
        </div>
      </details> : null}
    </article>;
  }
  const scalableCard = scalable ? <ScalableCard key="scalable" setting={<ScalableLiveToggle live={settings.artifact_scalable_data === "live"} />}>
      {scalable.portfolio ? <ScalablePortfolioView portfolio={scalable.portfolio as ScalablePortfolio} locale={locale} /> : <p className="text-sm text-muted-foreground">Holdings appear after the first sync.</p>}
  </ScalableCard> : null;
  const others = active.filter(account => !fedIds.has(account.id));

  return <main className="mx-auto w-full max-w-[1400px] space-y-8 px-4 py-6 sm:px-8 lg:py-8">
    <header className="space-y-4">
      <div className="relative flex flex-wrap items-end justify-between gap-4">
        <div className="flex flex-col gap-1"><p className="eyebrow">Money · balances and sources</p><h1 className="page-title">Accounts</h1></div>
        <AddAccountPanel>
          <SafeForm action={addAccountSafely} className="absolute right-0 z-10 mt-2 grid w-72 max-w-full gap-3 rounded-xl border border-border bg-card p-4 shadow-lg">
            <label className="grid gap-1 text-sm">Name<input name="name" className={field} maxLength={120} required /></label>
            <div className="flex gap-3">
              <label className="grid flex-1 gap-1 text-sm">Type<select name="type" className={field}>{accountTypes.map(type => <option key={type} value={type}>{type[0].toUpperCase() + type.slice(1)}</option>)}</select></label>
              <label className="grid gap-1 text-sm">Currency<input name="currency" className={`${field} w-20 uppercase`} defaultValue={workspace.display_currency} pattern="[A-Za-z]{3}" maxLength={3} required /></label>
            </div>
            <p className="text-xs text-muted-foreground">Currency can’t be changed later.</p>
            <button className="min-h-9 rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground hover:opacity-90">Add account</button>
            <button type="button" data-close className="min-h-9 rounded-lg px-3 py-1.5 text-sm text-muted-foreground hover:bg-muted">Cancel</button>
          </SafeForm>
        </AddAccountPanel>
      </div>
      {totals.size ? <dl className="rounded-xl border border-border bg-card px-5 py-4"><dt className="text-xs text-muted-foreground">Total{counted === active.length ? ` across ${active.length} active ${active.length === 1 ? "account" : "accounts"}` : ""}</dt>
        {[...totals].map(([currency, amount]) => <dd key={currency} className="mt-1 font-mono text-2xl font-semibold tabular-nums">{formatMoney(amount, currency, locale)}</dd>)}<dd className="mt-1"><CoverageNote counted={counted} total={active.length} /></dd></dl>
        : active.length ? <p className="rounded-xl border border-warning/40 bg-card px-5 py-4 text-sm text-warning">Total unavailable: {active.length} {active.length === 1 ? "account needs" : "accounts need"} a usable balance. <a className="underline" href="#needs-balance">Review {active.length === 1 ? "it" : "them"}</a>.</p> : null}
    </header>

    <ConnectedArea locale={locale} timeZone={timeZone} result={bank} connect={connect} initial={bankConnections as ConnectionsData} feeds={feeds} hasScalable={Boolean(scalable)} scalable={scalableCard} />

    {others.length ? <section id="needs-balance" className="scroll-mt-20 space-y-3" aria-labelledby="other-accounts"><h2 id="other-accounts" className="text-base font-semibold">Imported and entered by hand</h2>
      <div className="divide-y divide-border rounded-xl border border-border bg-card">{others.map(account => row(account))}</div></section>
      : !active.length ? <p className="rounded-xl border border-border bg-card p-6 text-sm text-muted-foreground">No accounts yet. Use Add account to connect a bank or Scalable, <Link className="underline" href="/import">import a statement</Link> or enter one by hand.</p> : null}

    <OwnAccounts identifiers={identifiers ?? []} accounts={active.map(account => ({ id: account.id, name: account.name }))} transfers={transfers}
      banked={(bankAccounts ?? []).flatMap(item => item.iban ? [{ iban: item.iban, name: item.account_name }] : [])} />

    {archived.length ? <section className="space-y-2 opacity-80" aria-label="Archived accounts"><h2 className="text-sm font-medium text-muted-foreground">Archived accounts ({archived.length})</h2><div className="divide-y divide-border rounded-xl border border-border bg-card">{archived.map(account => row(account))}</div></section> : null}

    <Suspense fallback={<div className="h-10" aria-busy="true" />}><AccountHistory accounts={accounts} /></Suspense>
  </main>;
}

async function AccountHistory({ accounts }: { accounts: Resolved[] }) {
  const { supabase, workspace: { id, locale, timezone: timeZone } } = await requireWorkspace();
  const { data: history, error: historyError } = await supabase.from("money_metadata_events").select("id,entity_type,entity_id,before,after,created_at,undone_at,undo_of").eq("workspace_id", id).order("created_at", { ascending: false }).limit(30);
  if (historyError) throw new Error("Could not load account and saved view history");
  const viewIds = [...new Set((history ?? []).filter(event => event.entity_type === "transaction_view" && !event.undone_at && !event.undo_of).map(event => event.entity_id))];
  const { data: views, error: viewsError } = viewIds.length ? await supabase.from("transaction_views").select("id,version").eq("workspace_id", id).in("id", viewIds) : { data: [], error: null };
  if (viewsError) throw new Error("Could not load account and saved view history");
  const versions = new Map<string, number>([...accounts.map(account => [account.id, account.version ?? 1] as const), ...(views ?? []).map(view => [view.id, view.version] as const)]);
  const events = (history ?? []) as MetaEvent[];
  const latestVersion = new Map<string, number>();
  for (const event of events) if (!event.undone_at && !event.undo_of)
    latestVersion.set(event.entity_id, Math.max(latestVersion.get(event.entity_id) ?? 0, Number(event.after?.version ?? 0)));
  const canUndo = (event: MetaEvent) => !event.undone_at && !event.undo_of && versions.has(event.entity_id) && Number(event.after?.version ?? 0) >= (latestVersion.get(event.entity_id) ?? 0);
  const when = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "medium", timeStyle: "short" });
  return events.length ? <section><h2 className="text-sm font-medium text-muted-foreground">Account and saved view history</h2>
      <ul className="mt-2 divide-y divide-border text-sm">{events.map(event => <li key={event.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
        <span>{describeEvent(event)} <span className="text-muted-foreground">· {when.format(new Date(event.created_at))}{event.undone_at ? " · Undone" : event.undo_of ? " · Restored by undo" : ""}</span></span>
        {canUndo(event) ? <SafeForm action={undoMoneyMetadataSafely}><input type="hidden" name="eventId" value={event.id} /><input type="hidden" name="version" value={versions.get(event.entity_id)} /><input type="hidden" name="requestId" value={randomUUID()} /><button aria-label={`Undo: ${describeEvent(event)}`} className={field}>Undo</button></SafeForm> : null}
      </li>)}</ul>
    </section> : null;
}

