241	  const before = firstSyncedOn(valuationHistory(events, items, timeZone), scalableKnownIds([connection.portfolio as ScalableExtras | null]));
242	  if (!before) return "skipped";
243	  const failed = async (reason: string) => {
244	    const saved = await db.from("scalable_connections").update({ history_status: "failed", history_checked_on: today, history_error: reason.slice(0, 1000) }).eq("id", connection.id);
245	    if (saved.error) throw new Error(saved.error.message);
246	    return "failed" as const;
247	  };
248	  try {
249	    const known = await db.from("scalable_trade_details").select("provider_id, isin, price_text").eq("workspace_id", connection.workspace_id).limit(100000);
250	    if (known.error) throw new Error(known.error.message);
251	    const details: TradeDetails = {
252	      known: new Map((known.data ?? []).map(row => [row.provider_id, { isin: row.isin, price: row.price_text }])),
253	      remember: async (id, detail) => {
254	        const remembered = await db.from("scalable_trade_details").upsert({ workspace_id: connection.workspace_id, provider_id: id, isin: detail.isin, price_text: detail.price });
255	        if (remembered.error) throw new Error(remembered.error.message);
256	      },
257	    };
258	    const input = await withScalable(connection.id, connection.workspace_id, mcp => readHistoryInput(mcp, timeZone, before, details), fetch, LOGIN_NEEDED_MS);
259	    try { await saveCharts(connection.id, { charts: [], trades: historyTradeRows(input.rows), held: null }); } catch (cause) { console.error("Scalable trades were not saved", cause); }
260	    const result = calculateHistory(input);
261	    if (!result.ok) return await failed(result.reason);
262	    const saved = await db.rpc("replace_scalable_value_history", { p_connection_id: connection.id, p_checked_on: today,
263	      p_rows: result.days.map(day => ({ on_date: day.date, currency_code: "EUR", securities_minor: day.securitiesMinor.toString(), crypto_minor: day.cryptoMinor.toString(), cash_minor: day.cashMinor.toString(), total_minor: day.totalMinor.toString() })) });
264	    if (saved.error) throw new Error(saved.error.message);
265	    return "saved";
266	  } catch (error) {
267	    return failed(error instanceof Error ? error.message : "Scalable could not be read");
268	  }
269	}
270	-- The price chart of each Scalable position as of the last sync, and the owner's own settled buys and sells of it, so the
271	-- Wealth detail opens with no call to Scalable. Prices are decimal text. A disconnect removes both tables' rows for the
272	-- workspace; reset all data removes them with the workspace.
273	create table public.scalable_security_charts (
274	  workspace_id uuid not null references public.workspaces(id) on delete cascade,
275	  isin text not null check (isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'),
276	  timeframe text not null check (timeframe in ('one_day','seven_days','one_month','one_year','max')),
277	  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
278	  points jsonb not null check (jsonb_typeof(points) = 'array'),
279	  fetched_at timestamptz not null,
280	  primary key (workspace_id, isin, timeframe)
281	);
282	alter table public.scalable_security_charts enable row level security;
283	create policy scalable_security_charts_owner_select on public.scalable_security_charts for select to authenticated using (public.owns_workspace(workspace_id));
284	revoke all on public.scalable_security_charts from public, anon, authenticated;
285	grant select on public.scalable_security_charts to authenticated;
286	grant all on public.scalable_security_charts to service_role;
