289	  workspace_id uuid not null references public.workspaces(id) on delete cascade,
290	  provider_id text not null check (char_length(provider_id) between 1 and 200),
291	  isin text not null check (isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'),
292	  side text not null check (side in ('BUY','SELL')),
293	  occurred_at timestamptz not null,
