304	create function public.save_scalable_charts(p_connection_id uuid, p_charts jsonb, p_trades jsonb, p_held text[]) returns void
305	language plpgsql security definer set search_path='' as $$
306	declare connection public.scalable_connections%rowtype;
307	begin
308	  if p_connection_id is null or jsonb_typeof(p_charts) is distinct from 'array' or jsonb_typeof(p_trades) is distinct from 'array' then
309	    raise exception 'Invalid Scalable charts' using errcode = '22023'; end if;
310	  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
