312	  insert into public.scalable_security_charts(workspace_id, isin, timeframe, currency_code, points, fetched_at)
313	    select connection.workspace_id, chart.isin, chart.timeframe, chart.currency_code, chart.points, chart.fetched_at
314	    from jsonb_to_recordset(p_charts) as chart(isin text, timeframe text, currency_code text, points jsonb, fetched_at timestamptz)
315	    on conflict (workspace_id, isin, timeframe) do update set currency_code = excluded.currency_code, points = excluded.points, fetched_at = excluded.fetched_at;
316	  insert into public.scalable_security_trades(workspace_id, provider_id, isin, side, occurred_at, quantity_text)
317	    select connection.workspace_id, trade.provider_id, trade.isin, trade.side, trade.occurred_at, trade.quantity_text
318	    from jsonb_to_recordset(p_trades) as trade(provider_id text, isin text, side text, occurred_at timestamptz, quantity_text text)
319	    on conflict (workspace_id, provider_id) do update set isin = excluded.isin, side = excluded.side, occurred_at = excluded.occurred_at, quantity_text = excluded.quantity_text;
320	  if p_held is not null then
321	    delete from public.scalable_security_charts where workspace_id = connection.workspace_id and isin <> all(p_held);
322	  end if;
