365	begin
366	  if p_connection_id is null or p_checked_on is null or jsonb_typeof(p_rows) is distinct from 'array' then
367	    raise exception 'Invalid Scalable value history' using errcode = '22023'; end if;
368	  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
369	  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
