371	  insert into public.scalable_value_history(workspace_id, on_date, currency_code, securities_minor, crypto_minor, cash_minor, total_minor)
372	    select connection.workspace_id, row.on_date, row.currency_code, row.securities_minor, row.crypto_minor, row.cash_minor, row.total_minor
373	    from jsonb_to_recordset(p_rows) as row(on_date date, currency_code text, securities_minor bigint, crypto_minor bigint, cash_minor bigint, total_minor bigint);
374	  get diagnostics saved = row_count;
