import { serviceDb } from "@/lib/service-db";
import { calendarDate } from "@/lib/finance/calendar";
import { loadWorkspaceSettings } from "@/lib/settings";
import { ScalableError } from "./client";
import { readCharts, saveCharts, tradeRows } from "./charts";
import { investmentsWatchlist, readTransactions, tradingAccess } from "./live";
import { cashSchema, holdingsSchema, overviewSchema, scalableWealth, type ScalableExtras } from "./portfolio";
import { withScalable } from "./server";
import { saveTransfers, transferRows } from "./transfers";

const optionalExtraIsSkipped = () => undefined;
const RECENT_TRANSACTIONS = 100, ACTIVITY_SHOWN = 8;

export async function syncScalable(connectionId: string, workspaceId: string) {
  const db = serviceDb();
  try {
    const { timezone } = await loadWorkspaceSettings(db, workspaceId);
    const previous = await db.from("scalable_connections").select("portfolio").eq("workspace_id", workspaceId).not("portfolio", "is", null);
    const fetchedAt = new Date().toISOString();
    const { snapshot, extras, access, recent, charts } = await withScalable(connectionId, workspaceId, async mcp => {
      const [holdings, overview, cash, activity, watchlist, access] = await Promise.all([mcp.callTool("get_portfolio_holdings"), mcp.callTool("get_portfolio_overview", { includeYearToDate: true }),
        mcp.callTool("get_portfolio_cash_breakdown"), mcp.callTool("list_portfolio_transactions", { pageSize: RECENT_TRANSACTIONS }).catch(optionalExtraIsSkipped),
        investmentsWatchlist(mcp).catch(optionalExtraIsSkipped), tradingAccess(mcp).catch(optionalExtraIsSkipped)]);
      const held = [...new Set(holdingsSchema.parse(holdings).holdings.filter(holding => holding.position.filled > 0).map(holding => holding.isin))];
      const charts = await readCharts(mcp, held, fetchedAt);
      const shown = (() => { try { return activity === undefined ? undefined : readTransactions(activity).slice(0, ACTIVITY_SHOWN); } catch { return undefined; } })();
      return { access, recent: activity, charts: { ...charts, held }, snapshot: { holdings: holdingsSchema.parse(holdings), overview: overviewSchema.parse(overview), cash: cashSchema.parse(cash) },
        extras: { ...(shown ? { activity: shown.map(({ id, date, status, type, description, shares, amountMinor, currencyCode }) => ({ id, date, status, type, description, shares, amountMinor, currencyCode })) } : {}),
          ...(watchlist ? { watchlist: watchlist.items.slice(0, 12).map(item => ({ isin: item.isin, name: item.name, priceMinor: item.quote?.priceMinor ?? null, currencyCode: item.quote?.currencyCode ?? "EUR", dayPercent: item.dayPercent })) } : {}) } };
    });
    const { items, portfolio } = scalableWealth(snapshot, workspaceId, calendarDate(new Date(), timezone));
    const known = new Set([...(previous.data ?? []).flatMap(row => { const ids = (row.portfolio as ScalableExtras | null); return [...(ids?.knownItemIds ?? []), ...(ids?.itemIds ?? [])]; }), ...items.map(item => item.id)]);
    const { data, error } = await db.rpc("sync_scalable_wealth", { p_connection_id: connectionId, p_items: items, p_portfolio: { ...portfolio, ...extras, knownItemIds: [...known] }, p_fetched_at: fetchedAt });
    if (error) throw new Error(error.message);
    if (recent !== undefined) try { await saveTransfers(connectionId, transferRows(recent, timezone), false); } catch (cause) { console.error("Scalable transfers were not saved", cause); }
    try {
      if (charts.failed) console.error(`Scalable charts missing for ${charts.failed} requests`);
      await saveCharts(connectionId, { charts: charts.rows, trades: recent === undefined ? [] : tradeRows(recent), held: charts.held });
    } catch (cause) { console.error("Scalable charts were not saved", cause); }
    if (access) {
      const saved = await db.from("scalable_connections").update({ trading_access: access }).eq("id", connectionId);
      if (saved.error) throw new Error(saved.error.message);
    }
    return { changed: data as number, portfolio };
  } catch (error) {
    if (!(error instanceof ScalableError && error.expired))
      await db.from("scalable_connections").update({ last_error: "The Scalable sync failed. It retries on the next sync." }).eq("id", connectionId);
    throw error;
  }
}
import { z } from "zod";
import { serviceDb } from "@/lib/service-db";
import { minorDigits } from "@/lib/finance/fx";
import type { ScalableMcp } from "./client";
import { scalableConfigured } from "./server";

export const READ_ONLY_TRADING = "Your Scalable connection only allows read access, so Moneo can't buy or sell for you. To trade from Moneo, turn on full access for AI agents in the Scalable app under Profile → Security.";

export async function activeScalableConnection(workspaceId: string): Promise<{ id: string; tradingAccess: "full" | "read" | null } | null> {
  if (!scalableConfigured()) return null;
  const { data, error } = await serviceDb().from("scalable_connections").select("id, trading_access").eq("workspace_id", workspaceId).eq("status", "active")
    .order("created_at", { ascending: false }).limit(1).maybeSingle();
  if (error) throw new Error(error.message);
  return data ? { id: data.id, tradingAccess: data.trading_access === "full" || data.trading_access === "read" ? data.trading_access : null } : null;
}

export async function tradingAccess(mcp: Pick<ScalableMcp, "listTools">): Promise<"full" | "read"> {
  const names = new Set((await mcp.listTools()).map(tool => tool.name));
  return ["preview_buy_order", "preview_sell_order", "submit_buy_order", "submit_sell_order"].every(name => names.has(name)) ? "full" : "read";
}

const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
const code = z.string().regex(/^[A-Z]{3}$/);
export function toMinor(value: number | string, currency: string): string {
  const text = typeof value === "number" ? value.toFixed(12) : value;
  const negative = text.startsWith("-"), [whole, fraction = ""] = (negative ? text.slice(1) : text).split(".");
  const digits = minorDigits(currency), padded = fraction.padEnd(digits + 1, "0");
  let minor = BigInt(whole + padded.slice(0, digits));
  if (Number(padded[digits]) >= 5) minor += 1n;
  return (negative && minor !== 0n ? -minor : minor).toString();
}
const percent = (gain: bigint, cost: bigint) => cost > 0n ? Number(gain * 10000n / cost) / 100 : null;

const holdingsSchema = z.object({
  holdings: z.array(z.object({ isin: z.string(), name: z.string(), fifoPrice: decimal.nullable().optional(), valuation: decimal, valuationCurrency: code,
    currentQuote: z.object({ midPrice: decimal, currency: code, timestamp: z.string().optional() }), position: z.object({ filled: decimal, pending: decimal.optional() }) })).default([]),
  cryptoHoldings: z.array(z.object({ ticker: z.string(), name: z.string(), position: z.object({ filled: decimal }).nullable().optional() })).default([]),
});
const overviewSchema = z.object({
  valuation: z.object({ total: decimal, securities: decimal.default(0), crypto: decimal.default(0) }),
  timestamps: z.object({ valuationTimestampUtc: z.string() }).partial().optional(),
  performance: z.array(z.object({ timeframe: z.string(), simpleAbsoluteReturn: decimal.nullable() })).default([]),
});
const cashSchema = z.object({ cash: z.object({ cashBalance: decimal, buyingPower: decimal.optional(), pendingBuyOrdersAmount: decimal.optional() }) });

export const PERIODS: Record<string, string> = { INTRADAY: "Latest market day", ONE_WEEK: "1 week", ONE_MONTH: "1 month", THREE_MONTHS: "3 months", SIX_MONTHS: "6 months",
  YEAR_TO_DATE: "This year", ONE_YEAR: "1 year", MAX: "All time" };

export async function investmentsPortfolio(mcp: ScalableMcp, currency = "EUR") {
  const [holdings, overview, cash, access] = await Promise.all([mcp.callTool("get_portfolio_holdings").then(value => holdingsSchema.parse(value)),
    mcp.callTool("get_portfolio_overview", { includeYearToDate: true }).then(value => overviewSchema.parse(value)),
    mcp.callTool("get_portfolio_cash_breakdown").then(value => cashSchema.parse(value)), tradingAccess(mcp)]);
  const positions = holdings.holdings.filter(holding => Number(holding.position.filled) > 0).map(holding => {
    const shares = Number(holding.position.filled), valueMinor = BigInt(toMinor(holding.valuation, holding.valuationCurrency));
    const costMinor = holding.fifoPrice ? BigInt(toMinor(Number(holding.fifoPrice) * shares, holding.valuationCurrency)) : null;
    return { isin: holding.isin, name: holding.name, shares: String(holding.position.filled), currencyCode: holding.valuationCurrency,
      priceMinor: toMinor(holding.currentQuote.midPrice, holding.currentQuote.currency), valueMinor: valueMinor.toString(),
      costMinor: costMinor?.toString() ?? null, gainMinor: costMinor === null ? null : (valueMinor - costMinor).toString(),
      gainPercent: costMinor === null ? null : percent(valueMinor - costMinor, costMinor) };
  }).sort((a, b) => Number(BigInt(b.valueMinor) - BigInt(a.valueMinor)));
  return {
    valuedAt: overview.timestamps?.valuationTimestampUtc ?? null, currencyCode: currency, tradingAccess: access,
    totalMinor: toMinor(overview.valuation.total, currency), securitiesMinor: toMinor(overview.valuation.securities, currency),
    cryptoMinor: toMinor(overview.valuation.crypto, currency), cashMinor: toMinor(cash.cash.cashBalance, currency),
    buyingPowerMinor: toMinor(cash.cash.buyingPower ?? cash.cash.cashBalance, currency), pendingBuyOrdersMinor: toMinor(cash.cash.pendingBuyOrdersAmount ?? 0, currency),
    returns: Object.keys(PERIODS).flatMap(timeframe => { const entry = overview.performance.find(item => item.timeframe === timeframe);
      return entry && entry.simpleAbsoluteReturn !== null ? [{ period: PERIODS[timeframe], returnMinor: toMinor(entry.simpleAbsoluteReturn, currency) }] : []; }),
    positions,
    crypto: holdings.cryptoHoldings.filter(coin => Number(coin.position?.filled ?? 0) > 0).map(coin => ({ name: coin.name, ticker: coin.ticker, quantity: String(coin.position!.filled) })),
  };
}

const transactionsSchema = z.object({ transactions: z.array(z.object({
  id: z.string(), kind: z.string(), status: z.string(), currency: code.optional(), lastEventAt: z.string(), description: z.string().nullable().optional(),
  security: z.object({ isin: z.string(), transactionType: z.string().nullable().optional(), quantity: decimal.nullable().optional(), amount: decimal.nullable().optional(),
    side: z.string().nullable().optional(), limitPrice: decimal.nullable().optional() }).nullable().optional(),
  cash: z.object({ transactionType: z.string().nullable().optional(), amount: decimal.nullable().optional() }).nullable().optional(),
  nonTradeSecurity: z.object({ isin: z.string().nullable().optional(), transactionType: z.string().nullable().optional(), amount: decimal.nullable().optional() }).passthrough().nullable().optional(),
})).default([]), page: z.object({ nextCursor: z.string().nullable().optional(), totalCount: z.number().optional() }).optional() });

export const transactionsInput = z.object({
  from: z.iso.date().optional().describe("First day, inclusive"), to: z.iso.date().optional().describe("Last day, inclusive"),
  isin: z.string().regex(/^[A-Z]{2}[A-Z0-9]{9}\d$/).optional(), search: z.string().trim().min(1).max(100).optional(),
  types: z.array(z.string().max(40)).max(5).optional().describe("e.g. buy, sell, deposit, withdrawal, dividend"),
  statuses: z.array(z.string().max(40)).max(5).optional().describe("e.g. pending for open orders, settled, cancelled"),
  limit: z.number().int().min(1).max(50).optional(),
  cursor: z.string().min(1).max(4000).optional().describe("nextCursor from the previous page, with the same filters"),
  allPages: z.boolean().optional().describe("Fetch the complete matching security transaction stream, deduplicated by id; fails if pagination cannot finish"),
}).strict();

export type InvestmentTransaction = ReturnType<typeof readTransactions>[number];
export function readTransactions(value: unknown) {
  return transactionsSchema.parse(value).transactions.map(row => {
    const currency = row.currency ?? "EUR", amount = row.security?.amount ?? row.cash?.amount ?? row.nonTradeSecurity?.amount ?? null;
    return { id: row.id, date: row.lastEventAt.slice(0, 10), status: row.status, description: row.description ?? null,
      type: (row.security?.side ?? row.security?.transactionType ?? row.cash?.transactionType ?? row.nonTradeSecurity?.transactionType ?? row.kind).toString().toLowerCase(),
      isin: row.security?.isin ?? row.nonTradeSecurity?.isin ?? null, shares: row.security?.quantity == null ? null : String(row.security.quantity),
      limitPriceMinor: row.security?.limitPrice == null ? null : toMinor(row.security.limitPrice, currency),
      currencyCode: currency, amountMinor: amount === null ? null : toMinor(amount, currency) };
  });
}

export async function investmentsTransactions(mcp: ScalableMcp, input: z.infer<typeof transactionsInput>): Promise<{ transactions: InvestmentTransaction[]; more: boolean; nextCursor: string | null; totalCount: number | null }> {
  if (input.allPages) {
    if (input.cursor) throw new Error("Complete history must start without a cursor");
    const rows = new Map<string, InvestmentTransaction>(), seen = new Set<string>();
    let cursor: string | undefined;
    for (let count = 0; count < 200; count++) {
      const page = await investmentsTransactions(mcp, { ...input, allPages: false, cursor, limit: 50 });
      for (const row of page.transactions) rows.set(row.id, row);
      if (!page.nextCursor) return { transactions: [...rows.values()], more: false, nextCursor: null, totalCount: page.totalCount };
      if (seen.has(page.nextCursor)) throw new Error("Scalable repeated its transaction cursor; history is incomplete");
      seen.add(page.nextCursor); cursor = page.nextCursor;
    }
    throw new Error("Scalable history exceeded 200 pages; narrow the filters");
  }
  const raw = await mcp.callTool("list_portfolio_transactions", { pageSize: input.limit ?? 20,
    ...(input.cursor ? { cursor: input.cursor } : {}),
    ...(input.from ? { fromTime: `${input.from}T00:00:00.000Z` } : {}), ...(input.to ? { toTime: `${input.to}T23:59:59.999Z` } : {}),
    ...(input.isin ? { isin: input.isin } : {}), ...(input.search ? { searchTerm: input.search } : {}),
    ...(input.types ? { transactionTypes: input.types } : {}), ...(input.statuses ? { statuses: input.statuses } : {}) });
  const page = transactionsSchema.parse(raw).page;
  if (page?.nextCursor && page.nextCursor === input.cursor) throw new Error("Scalable repeated its transaction cursor; history is incomplete");
  return { transactions: readTransactions(raw), more: Boolean(page?.nextCursor), nextCursor: page?.nextCursor ?? null, totalCount: page?.totalCount ?? null };
}

export const securityInput = z.object({
  action: z.enum(["search", "quote", "chart", "news"]),
  query: z.string().trim().min(1).max(100).optional().describe("search: a name, ticker or ISIN"),
  isin: z.string().regex(/^[A-Z]{2}[A-Z0-9]{9}\d$/).optional().describe("quote, chart and news"),
  timeframe: z.enum(["one_day", "seven_days", "one_month", "three_months", "six_months", "year_to_date", "one_year", "max"]).optional().describe("chart only; default one_month"),
}).strict();

const quoteSchema = z.object({ midPrice: decimal, currency: code, timestampUtc: z.string().optional(), isOutdated: z.boolean().optional() }).passthrough();
const searchSchema = z.object({ results: z.array(z.object({ isin: z.string(), name: z.string(), securityType: z.string().optional(), currentQuote: quoteSchema.nullable().optional() })).default([]) });
const chartSchema = z.object({ currency: code, dataPoints: z.array(z.object({ midPrice: decimal, timestampUtc: z.string() })).default([]) });
const newsSchema = z.object({ summary: z.object({ short: z.string().optional(), long: z.string().optional() }).nullable().optional() });
const quoteResultSchema = z.object({ security: z.object({ isin: z.string(), name: z.string().optional(), securityType: z.string().optional(),
  quote: quoteSchema.and(z.object({ performances: z.array(z.object({ timeframe: z.string(), performance: decimal.nullable().optional() })).optional() })) }) });
const quoted = (quote: z.infer<typeof quoteSchema> | null | undefined) => quote ? { priceMinor: toMinor(quote.midPrice, quote.currency), currencyCode: quote.currency, at: quote.timestampUtc ?? null, outdated: quote.isOutdated ?? false } : null;

export async function investmentsSecurity(mcp: ScalableMcp, input: z.infer<typeof securityInput>) {
  if (input.action === "search") {
    if (!input.query) throw new Error("Search needs a query");
    const found = searchSchema.parse(await mcp.callTool("search_securities", { query: input.query }));
    return { results: found.results.slice(0, 10).map(item => ({ isin: item.isin, name: item.name, type: item.securityType ?? null, quote: quoted(item.currentQuote) })) };
  }
  if (!input.isin) throw new Error(`${input.action} needs an ISIN; search first`);
  if (input.action === "quote") {
    const { security } = quoteResultSchema.parse(await mcp.callTool("get_security_quote", { isin: input.isin }));
    return { isin: security.isin, name: security.name ?? null, type: security.securityType ?? null, quote: quoted(security.quote),
      moves: (security.quote.performances ?? []).flatMap(entry => PERIODS[entry.timeframe] && entry.performance != null ? [{ period: PERIODS[entry.timeframe], percent: Math.round(Number(entry.performance) * 10000) / 100 }] : []) };
  }
  if (input.action === "chart") {
    const timeframe = input.timeframe ?? "one_month";
    const chart = chartSchema.parse(await mcp.callTool("get_security_chart", { isin: input.isin, timeframe }));
    const prices = chart.dataPoints.map(point => Number(point.midPrice));
    if (!prices.length) return { isin: input.isin, timeframe, points: [] };
    const first = prices[0], last = prices.at(-1)!;
    const step = Math.max(1, Math.ceil(chart.dataPoints.length / 24));
    return { isin: input.isin, timeframe, currencyCode: chart.currency, firstMinor: toMinor(first, chart.currency), lastMinor: toMinor(last, chart.currency),
      lowMinor: toMinor(Math.min(...prices), chart.currency), highMinor: toMinor(Math.max(...prices), chart.currency), changePercent: Math.round((last - first) / first * 10000) / 100,
      points: chart.dataPoints.filter((_, index) => index % step === 0 || index === chart.dataPoints.length - 1).map(point => ({ at: point.timestampUtc, priceMinor: toMinor(point.midPrice, chart.currency) })) };
  }
  const news = newsSchema.parse(await mcp.callTool("get_security_news", { isin: input.isin, locale: "en_US" }));
  return { isin: input.isin, summary: news.summary?.short ?? null, detail: news.summary?.long?.slice(0, 2500) ?? null };
}

const dayMove = (quote: unknown) => {
  const today = (quote as { performances?: { timeframe?: string; performance?: number | string | null }[] } | null)?.performances?.find(entry => entry.timeframe === "INTRADAY")?.performance;
  return today == null ? null : Math.round(Number(today) * 10000) / 100;
};
const watchlistSchema = z.object({ items: z.array(z.object({ isin: z.string(), name: z.string(), securityType: z.string().optional(), currentQuote: quoteSchema.nullable().optional() })).default([]) });
export async function investmentsWatchlist(mcp: ScalableMcp) {
  return { items: watchlistSchema.parse(await mcp.callTool("list_watchlist_items")).items.map(item => ({ isin: item.isin, name: item.name, type: item.securityType ?? null, quote: quoted(item.currentQuote),
    dayPercent: dayMove(item.currentQuote) })) };
}
import { firstSyncedOn, loadWealthEvents, scalableKnownIds, valuationHistory } from "@/lib/finance/net-worth";
import { serviceDb } from "@/lib/service-db";
import { loadWealthItems } from "@/lib/finance/wealth";
import { historyTradeRows, saveCharts } from "./charts";
import { calculateHistory, readHistoryInput, type TradeDetails } from "./history";
import type { ScalableExtras } from "./portfolio";
import { withScalable } from "./server";

const LOGIN_NEEDED_MS = 600_000;

export async function rebuildScalableHistory(connection: { id: string; workspace_id: string; portfolio: unknown }, timeZone: string, today: string): Promise<"saved" | "failed" | "skipped"> {
  const db = serviceDb();
  const [events, items] = await Promise.all([loadWealthEvents(db, connection.workspace_id), loadWealthItems(db, connection.workspace_id, true)]);
  const before = firstSyncedOn(valuationHistory(events, items, timeZone), scalableKnownIds([connection.portfolio as ScalableExtras | null]));
  if (!before) return "skipped";
  const failed = async (reason: string) => {
    const saved = await db.from("scalable_connections").update({ history_status: "failed", history_checked_on: today, history_error: reason.slice(0, 1000) }).eq("id", connection.id);
    if (saved.error) throw new Error(saved.error.message);
    return "failed" as const;
  };
  try {
    const known = await db.from("scalable_trade_details").select("provider_id, isin, price_text").eq("workspace_id", connection.workspace_id).limit(100000);
    if (known.error) throw new Error(known.error.message);
    const details: TradeDetails = {
      known: new Map((known.data ?? []).map(row => [row.provider_id, { isin: row.isin, price: row.price_text }])),
      remember: async (id, detail) => {
        const remembered = await db.from("scalable_trade_details").upsert({ workspace_id: connection.workspace_id, provider_id: id, isin: detail.isin, price_text: detail.price });
        if (remembered.error) throw new Error(remembered.error.message);
      },
    };
    const input = await withScalable(connection.id, connection.workspace_id, mcp => readHistoryInput(mcp, timeZone, before, details), fetch, LOGIN_NEEDED_MS);
    try { await saveCharts(connection.id, { charts: [], trades: historyTradeRows(input.rows), held: null }); } catch (cause) { console.error("Scalable trades were not saved", cause); }
    const result = calculateHistory(input);
    if (!result.ok) return await failed(result.reason);
    const saved = await db.rpc("replace_scalable_value_history", { p_connection_id: connection.id, p_checked_on: today,
      p_rows: result.days.map(day => ({ on_date: day.date, currency_code: "EUR", securities_minor: day.securitiesMinor.toString(), crypto_minor: day.cryptoMinor.toString(), cash_minor: day.cashMinor.toString(), total_minor: day.totalMinor.toString() })) });
    if (saved.error) throw new Error(saved.error.message);
    return "saved";
  } catch (error) {
    return failed(error instanceof Error ? error.message : "Scalable could not be read");
  }
}
-- The price chart of each Scalable position as of the last sync, and the owner's own settled buys and sells of it, so the
-- Wealth detail opens with no call to Scalable. Prices are decimal text. A disconnect removes both tables' rows for the
-- workspace; reset all data removes them with the workspace.
create table public.scalable_security_charts (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  isin text not null check (isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'),
  timeframe text not null check (timeframe in ('one_day','seven_days','one_month','one_year','max')),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  points jsonb not null check (jsonb_typeof(points) = 'array'),
  fetched_at timestamptz not null,
  primary key (workspace_id, isin, timeframe)
);
alter table public.scalable_security_charts enable row level security;
create policy scalable_security_charts_owner_select on public.scalable_security_charts for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.scalable_security_charts from public, anon, authenticated;
grant select on public.scalable_security_charts to authenticated;
grant all on public.scalable_security_charts to service_role;

create table public.scalable_security_trades (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  provider_id text not null check (char_length(provider_id) between 1 and 200),
  isin text not null check (isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'),
  side text not null check (side in ('BUY','SELL')),
  occurred_at timestamptz not null,
  quantity_text text not null check (quantity_text ~ '^[0-9]+(\.[0-9]+)?$'),
  primary key (workspace_id, provider_id)
);
create index scalable_security_trades_isin on public.scalable_security_trades(workspace_id, isin, occurred_at);
alter table public.scalable_security_trades enable row level security;
create policy scalable_security_trades_owner_select on public.scalable_security_trades for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.scalable_security_trades from public, anon, authenticated;
grant select on public.scalable_security_trades to authenticated;
grant all on public.scalable_security_trades to service_role;

create function public.save_scalable_charts(p_connection_id uuid, p_charts jsonb, p_trades jsonb, p_held text[]) returns void
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype;
begin
  if p_connection_id is null or jsonb_typeof(p_charts) is distinct from 'array' or jsonb_typeof(p_trades) is distinct from 'array' then
    raise exception 'Invalid Scalable charts' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  insert into public.scalable_security_charts(workspace_id, isin, timeframe, currency_code, points, fetched_at)
    select connection.workspace_id, chart.isin, chart.timeframe, chart.currency_code, chart.points, chart.fetched_at
    from jsonb_to_recordset(p_charts) as chart(isin text, timeframe text, currency_code text, points jsonb, fetched_at timestamptz)
    on conflict (workspace_id, isin, timeframe) do update set currency_code = excluded.currency_code, points = excluded.points, fetched_at = excluded.fetched_at;
  insert into public.scalable_security_trades(workspace_id, provider_id, isin, side, occurred_at, quantity_text)
    select connection.workspace_id, trade.provider_id, trade.isin, trade.side, trade.occurred_at, trade.quantity_text
    from jsonb_to_recordset(p_trades) as trade(provider_id text, isin text, side text, occurred_at timestamptz, quantity_text text)
    on conflict (workspace_id, provider_id) do update set isin = excluded.isin, side = excluded.side, occurred_at = excluded.occurred_at, quantity_text = excluded.quantity_text;
  if p_held is not null then
    delete from public.scalable_security_charts where workspace_id = connection.workspace_id and isin <> all(p_held);
  end if;
end;
$$;
revoke all on function public.save_scalable_charts(uuid, jsonb, jsonb, text[]) from public, anon, authenticated;
grant execute on function public.save_scalable_charts(uuid, jsonb, jsonb, text[]) to service_role;

create function public.remove_scalable_charts(p_workspace_id uuid) returns void
language sql security definer set search_path='' as $$
  delete from public.scalable_security_trades where workspace_id = p_workspace_id;
  delete from public.scalable_security_charts where workspace_id = p_workspace_id;
$$;
revoke all on function public.remove_scalable_charts(uuid) from public, anon, authenticated;
grant execute on function public.remove_scalable_charts(uuid) to service_role;
-- Past Scalable values worked out from Scalable's own transactions and price charts. They are a calculation,
-- not a record, so they live apart from wealth_items and wealth_events: the event list stays the owner's real
-- history. Rows only exist for days before the first real synced value, and a run replaces all of them at once.
-- A disconnect keeps them, as it keeps synced wealth items; reset all data clears them.
create table public.scalable_value_history (
  workspace_id uuid not null references public.workspaces(id),
  on_date date not null,
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  securities_minor bigint not null,
  crypto_minor bigint not null,
  cash_minor bigint not null,
  total_minor bigint not null,
  primary key (workspace_id, on_date),
  check (total_minor = securities_minor + crypto_minor + cash_minor)
);
alter table public.scalable_value_history enable row level security;
create policy scalable_value_history_owner_select on public.scalable_value_history for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.scalable_value_history from public, anon, authenticated;
grant select on public.scalable_value_history to authenticated;
grant all on public.scalable_value_history to service_role;

-- The outcome of the last calculation. Kept apart from last_error, which tells the owner a sync needs attention.
alter table public.scalable_connections add column history_status text check (history_status in ('ok','failed')),
  add column history_checked_on date,
  add column history_error text check (char_length(history_error) <= 1000);
grant select (history_status, history_checked_on) on public.scalable_connections to authenticated;

create function public.replace_scalable_value_history(p_connection_id uuid, p_rows jsonb, p_checked_on date) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; saved integer;
begin
  if p_connection_id is null or p_checked_on is null or jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'Invalid Scalable value history' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  delete from public.scalable_value_history where workspace_id = connection.workspace_id;
  insert into public.scalable_value_history(workspace_id, on_date, currency_code, securities_minor, crypto_minor, cash_minor, total_minor)
    select connection.workspace_id, row.on_date, row.currency_code, row.securities_minor, row.crypto_minor, row.cash_minor, row.total_minor
    from jsonb_to_recordset(p_rows) as row(on_date date, currency_code text, securities_minor bigint, crypto_minor bigint, cash_minor bigint, total_minor bigint);
  get diagnostics saved = row_count;
  update public.scalable_connections set history_status = 'ok', history_checked_on = p_checked_on, history_error = null where id = p_connection_id;
  return saved;
end;
$$;
revoke all on function public.replace_scalable_value_history(uuid, jsonb, date) from public, anon, authenticated;
grant execute on function public.replace_scalable_value_history(uuid, jsonb, date) to service_role;

create or replace function public.reset_workspace() returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; owner uuid := auth.uid();
begin
  if owner is null then raise exception 'Unauthorized' using errcode='42501'; end if;
  select id into ws from public.workspaces where owner_id=owner for update;
  if not found then raise exception 'Workspace unavailable' using errcode='P0002'; end if;
  -- Deleted history is not undoable, so skip planning audit rows and link-edit guards.
  perform set_config('moneo.planning_undo','true',true);
  perform set_config('moneo.link_edit','on',true);

  -- Agent team runs, tasks and proposals.
  delete from public.agent_proposals where workspace_id=ws;
  delete from public.agent_tasks where workspace_id=ws;
  delete from public.agent_runs where workspace_id=ws;

  -- AI conversations and reviews.
  delete from public.saved_analyses where workspace_id=ws;
  delete from public.summary_runs where workspace_id=ws;
  delete from public.background_jobs where workspace_id=ws;
  delete from public.chat_requests where workspace_id=ws;
  delete from public.messages where workspace_id=ws;
  delete from public.conversations where workspace_id=ws;
  delete from public.dashboard_layouts where workspace_id=ws;

  -- Preferences, views and settings.
  delete from public.insight_dismissals where workspace_id=ws;
  delete from public.insight_preferences where workspace_id=ws;
  delete from public.financial_evidence_receipts where workspace_id=ws;
  delete from public.transaction_views where workspace_id=ws;
  delete from public.fx_rates where workspace_id=ws;
  delete from public.workspace_settings where workspace_id=ws;

  -- Everything that points at transactions.
  delete from public.transaction_link_fees where workspace_id=ws;
  delete from public.transaction_links where workspace_id=ws;
  delete from public.transaction_splits where workspace_id=ws;
  delete from public.transaction_split_sets where workspace_id=ws;
  delete from public.pending_hold_resolutions where workspace_id=ws;
  delete from public.correction_events where workspace_id=ws;
  delete from public.recurring_occurrence_settlements where workspace_id=ws;
  delete from public.recurring_series_transactions where workspace_id=ws;
  delete from public.recurring_series where workspace_id=ws;
  delete from public.manual_transaction_entries where workspace_id=ws;
  delete from public.money_metadata_events where workspace_id=ws;
  delete from public.organization_reviews where workspace_id=ws;
  delete from public.organization_rules where workspace_id=ws;
  delete from public.transaction_batches where workspace_id=ws;
  delete from public.scalable_value_history where workspace_id=ws;
  delete from public.wealth_events where workspace_id=ws;
  delete from public.wealth_items where workspace_id=ws;
  delete from public.transaction_sources where transaction_id in (select id from public.transactions where workspace_id=ws)
    or source_transaction_id in (select id from public.source_transactions where workspace_id=ws);
  delete from public.balance_snapshots where workspace_id=ws;
  update public.transactions set transfer_id=null, refund_of_id=null
    where workspace_id=ws and (transfer_id is not null or refund_of_id is not null);
  delete from public.transactions where workspace_id=ws;

  -- Bank connections, then imports.
  delete from public.bank_connection_accounts where workspace_id=ws;
  delete from public.bank_connections where workspace_id=ws;

  -- Imports.
  delete from public.source_transactions where workspace_id=ws;
  delete from public.import_control_events where workspace_id=ws;
  delete from public.import_staging where workspace_id=ws;
  delete from public.imports where workspace_id=ws;
  delete from public.data_sources where workspace_id=ws;

  -- Goals, plans, scenarios and budgets.
  delete from public.goal_reservation_events where workspace_id=ws;
  delete from public.goal_allocations where workspace_id=ws;
  delete from public.goal_events where workspace_id=ws;
  delete from public.goals where workspace_id=ws;
  delete from public.forecast_runs where workspace_id=ws;
  delete from public.scenario_overrides where workspace_id=ws;
  delete from public.scenario_events where workspace_id=ws;
  delete from public.scenarios where workspace_id=ws;
  delete from public.spending_plan_limits where workspace_id=ws;
  delete from public.spending_plans where workspace_id=ws;
  delete from public.financial_assumptions where workspace_id=ws;
  delete from public.planning_events where workspace_id=ws;
  delete from public.forecast_preference_events where workspace_id=ws;
  delete from public.forecast_preferences where workspace_id=ws;

  -- Remaining parents, then a fresh workspace exactly like create_private_workspace().
  delete from public.merchants where workspace_id=ws;
  delete from public.categories where workspace_id=ws;
  delete from public.accounts where workspace_id=ws;
  delete from public.workspaces where id=ws;
  insert into public.workspaces(owner_id) values(owner);
end;
$$;
revoke all on function public.reset_workspace() from public,anon;
grant execute on function public.reset_workspace() to authenticated;
-- What each Scalable trade's details say that its list row doesn't: the ETP behind a crypto row, and the price paid without
-- fees. A trade's details never change, so this keeps the daily calculation from asking about every trade on every run. Facts
-- about past trades, so a disconnect keeps them; reset all data removes them with the workspace.
create table public.scalable_trade_details (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  provider_id text not null,
  isin text not null,
  price_text text check (price_text ~ '^[0-9]+(\.[0-9]+)?$'),
  primary key (workspace_id, provider_id)
);
alter table public.scalable_trade_details enable row level security;
revoke all on public.scalable_trade_details from public, anon, authenticated;
grant all on public.scalable_trade_details to service_role;

