383	async function AccountHistory({ accounts }: { accounts: Resolved[] }) {
384	  const { supabase, workspace: { id, locale, timezone: timeZone } } = await requireWorkspace();
385	  const { data: history, error: historyError } = await supabase.from("money_metadata_events").select("id,entity_type,entity_id,before,after,created_at,undone_at,undo_of").eq("workspace_id", id).order("created_at", { ascending: false }).limit(30);
386	  if (historyError) throw new Error("Could not load account and saved view history");
387	  const viewIds = [...new Set((history ?? []).filter(event => event.entity_type === "transaction_view" && !event.undone_at && !event.undo_of).map(event => event.entity_id))];
388	  const { data: views, error: viewsError } = viewIds.length ? await supabase.from("transaction_views").select("id,version").eq("workspace_id", id).in("id", viewIds) : { data: [], error: null };
389	  if (viewsError) throw new Error("Could not load account and saved view history");
390	  const versions = new Map<string, number>([...accounts.map(account => [account.id, account.version ?? 1] as const), ...(views ?? []).map(view => [view.id, view.version] as const)]);
391	  const events = (history ?? []) as MetaEvent[];
392	  const latestVersion = new Map<string, number>();
393	  for (const event of events) if (!event.undone_at && !event.undo_of)
394	    latestVersion.set(event.entity_id, Math.max(latestVersion.get(event.entity_id) ?? 0, Number(event.after?.version ?? 0)));
395	  const canUndo = (event: MetaEvent) => !event.undone_at && !event.undo_of && versions.has(event.entity_id) && Number(event.after?.version ?? 0) >= (latestVersion.get(event.entity_id) ?? 0);
396	  const when = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "medium", timeStyle: "short" });
397	  return events.length ? <section><h2 className="text-sm font-medium text-muted-foreground">Account and saved view history</h2>
398	      <ul className="mt-2 divide-y divide-border text-sm">{events.map(event => <li key={event.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
399	        <span>{describeEvent(event)} <span className="text-muted-foreground">· {when.format(new Date(event.created_at))}{event.undone_at ? " · Undone" : event.undo_of ? " · Restored by undo" : ""}</span></span>
400	        {canUndo(event) ? <SafeForm action={undoMoneyMetadataSafely}><input type="hidden" name="eventId" value={event.id} /><input type="hidden" name="version" value={versions.get(event.entity_id)} /><input type="hidden" name="requestId" value={randomUUID()} /><button aria-label={`Undo: ${describeEvent(event)}`} className={field}>Undo</button></SafeForm> : null}
401	      </li>)}</ul>
402	    </section> : null;
403	}
