14	export async function syncScalable(connectionId: string, workspaceId: string) {
15	  const db = serviceDb();
16	  try {
17	    const { timezone } = await loadWorkspaceSettings(db, workspaceId);
18	    const previous = await db.from("scalable_connections").select("portfolio").eq("workspace_id", workspaceId).not("portfolio", "is", null);
19	    const fetchedAt = new Date().toISOString();
20	    const { snapshot, extras, access, recent, charts } = await withScalable(connectionId, workspaceId, async mcp => {
21	      const [holdings, overview, cash, activity, watchlist, access] = await Promise.all([mcp.callTool("get_portfolio_holdings"), mcp.callTool("get_portfolio_overview", { includeYearToDate: true }),
22	        mcp.callTool("get_portfolio_cash_breakdown"), mcp.callTool("list_portfolio_transactions", { pageSize: RECENT_TRANSACTIONS }).catch(optionalExtraIsSkipped),
23	        investmentsWatchlist(mcp).catch(optionalExtraIsSkipped), tradingAccess(mcp).catch(optionalExtraIsSkipped)]);
24	      const held = [...new Set(holdingsSchema.parse(holdings).holdings.filter(holding => holding.position.filled > 0).map(holding => holding.isin))];
25	      const charts = await readCharts(mcp, held, fetchedAt);
26	      const shown = (() => { try { return activity === undefined ? undefined : readTransactions(activity).slice(0, ACTIVITY_SHOWN); } catch { return undefined; } })();
27	      return { access, recent: activity, charts: { ...charts, held }, snapshot: { holdings: holdingsSchema.parse(holdings), overview: overviewSchema.parse(overview), cash: cashSchema.parse(cash) },
28	        extras: { ...(shown ? { activity: shown.map(({ id, date, status, type, description, shares, amountMinor, currencyCode }) => ({ id, date, status, type, description, shares, amountMinor, currencyCode })) } : {}),
29	          ...(watchlist ? { watchlist: watchlist.items.slice(0, 12).map(item => ({ isin: item.isin, name: item.name, priceMinor: item.quote?.priceMinor ?? null, currencyCode: item.quote?.currencyCode ?? "EUR", dayPercent: item.dayPercent })) } : {}) } };
30	    });
31	    const { items, portfolio } = scalableWealth(snapshot, workspaceId, calendarDate(new Date(), timezone));
32	    const known = new Set([...(previous.data ?? []).flatMap(row => { const ids = (row.portfolio as ScalableExtras | null); return [...(ids?.knownItemIds ?? []), ...(ids?.itemIds ?? [])]; }), ...items.map(item => item.id)]);
33	    const { data, error } = await db.rpc("sync_scalable_wealth", { p_connection_id: connectionId, p_items: items, p_portfolio: { ...portfolio, ...extras, knownItemIds: [...known] }, p_fetched_at: fetchedAt });
34	    if (error) throw new Error(error.message);
35	    if (recent !== undefined) try { await saveTransfers(connectionId, transferRows(recent, timezone), false); } catch (cause) { console.error("Scalable transfers were not saved", cause); }
36	    try {
37	      if (charts.failed) console.error(`Scalable charts missing for ${charts.failed} requests`);
38	      await saveCharts(connectionId, { charts: charts.rows, trades: recent === undefined ? [] : tradeRows(recent), held: charts.held });
39	    } catch (cause) { console.error("Scalable charts were not saved", cause); }
40	    if (access) {
41	      const saved = await db.from("scalable_connections").update({ trading_access: access }).eq("id", connectionId);
42	      if (saved.error) throw new Error(saved.error.message);
43	    }
44	    return { changed: data as number, portfolio };
45	  } catch (error) {
46	    if (!(error instanceof ScalableError && error.expired))
47	      await db.from("scalable_connections").update({ last_error: "The Scalable sync failed. It retries on the next sync." }).eq("id", connectionId);
48	    throw error;
49	  }
50	}
