74	export function toMinor(value: number | string, currency: string): string {
75	  const text = typeof value === "number" ? value.toFixed(12) : value;
76	  const negative = text.startsWith("-"), [whole, fraction = ""] = (negative ? text.slice(1) : text).split(".");
77	  const digits = minorDigits(currency), padded = fraction.padEnd(digits + 1, "0");
78	  let minor = BigInt(whole + padded.slice(0, digits));
79	  if (Number(padded[digits]) >= 5) minor += 1n;
80	  return (negative && minor !== 0n ? -minor : minor).toString();
81	}
