153	export async function investmentsTransactions(mcp: ScalableMcp, input: z.infer<typeof transactionsInput>): Promise<{ transactions: InvestmentTransaction[]; more: boolean; nextCursor: string | null; totalCount: number | null }> {
154	  if (input.allPages) {
155	    if (input.cursor) throw new Error("Complete history must start without a cursor");
156	    const rows = new Map<string, InvestmentTransaction>(), seen = new Set<string>();
157	    let cursor: string | undefined;
158	    for (let count = 0; count < 200; count++) {
159	      const page = await investmentsTransactions(mcp, { ...input, allPages: false, cursor, limit: 50 });
160	      for (const row of page.transactions) rows.set(row.id, row);
161	      if (!page.nextCursor) return { transactions: [...rows.values()], more: false, nextCursor: null, totalCount: page.totalCount };
162	      if (seen.has(page.nextCursor)) throw new Error("Scalable repeated its transaction cursor; history is incomplete");
163	      seen.add(page.nextCursor); cursor = page.nextCursor;
164	    }
165	    throw new Error("Scalable history exceeded 200 pages; narrow the filters");
166	  }
167	  const raw = await mcp.callTool("list_portfolio_transactions", { pageSize: input.limit ?? 20,
168	    ...(input.cursor ? { cursor: input.cursor } : {}),
169	    ...(input.from ? { fromTime: `${input.from}T00:00:00.000Z` } : {}), ...(input.to ? { toTime: `${input.to}T23:59:59.999Z` } : {}),
170	    ...(input.isin ? { isin: input.isin } : {}), ...(input.search ? { searchTerm: input.search } : {}),
171	    ...(input.types ? { transactionTypes: input.types } : {}), ...(input.statuses ? { statuses: input.statuses } : {}) });
172	  const page = transactionsSchema.parse(raw).page;
173	  if (page?.nextCursor && page.nextCursor === input.cursor) throw new Error("Scalable repeated its transaction cursor; history is incomplete");
