202	      moves: (security.quote.performances ?? []).flatMap(entry => PERIODS[entry.timeframe] && entry.performance != null ? [{ period: PERIODS[entry.timeframe], percent: Math.round(Number(entry.performance) * 10000) / 100 }] : []) };
203	  }
204	  if (input.action === "chart") {
205	    const timeframe = input.timeframe ?? "one_month";
206	    const chart = chartSchema.parse(await mcp.callTool("get_security_chart", { isin: input.isin, timeframe }));
207	    const prices = chart.dataPoints.map(point => Number(point.midPrice));
208	    if (!prices.length) return { isin: input.isin, timeframe, points: [] };
209	    const first = prices[0], last = prices.at(-1)!;
210	    const step = Math.max(1, Math.ceil(chart.dataPoints.length / 24));
211	    return { isin: input.isin, timeframe, currencyCode: chart.currency, firstMinor: toMinor(first, chart.currency), lastMinor: toMinor(last, chart.currency),
212	      lowMinor: toMinor(Math.min(...prices), chart.currency), highMinor: toMinor(Math.max(...prices), chart.currency), changePercent: Math.round((last - first) / first * 10000) / 100,
213	      points: chart.dataPoints.filter((_, index) => index % step === 0 || index === chart.dataPoints.length - 1).map(point => ({ at: point.timestampUtc, priceMinor: toMinor(point.midPrice, chart.currency) })) };
214	  }
215	  const news = newsSchema.parse(await mcp.callTool("get_security_news", { isin: input.isin, locale: "en_US" }));
216	  return { isin: input.isin, summary: news.summary?.short ?? null, detail: news.summary?.long?.slice(0, 2500) ?? null };
217	}
218	
219	const dayMove = (quote: unknown) => {
220	  const today = (quote as { performances?: { timeframe?: string; performance?: number | string | null }[] } | null)?.performances?.find(entry => entry.timeframe === "INTRADAY")?.performance;
221	  return today == null ? null : Math.round(Number(today) * 10000) / 100;
222	};
223	const watchlistSchema = z.object({ items: z.array(z.object({ isin: z.string(), name: z.string(), securityType: z.string().optional(), currentQuote: quoteSchema.nullable().optional() })).default([]) });
224	export async function investmentsWatchlist(mcp: ScalableMcp) {
225	  return { items: watchlistSchema.parse(await mcp.callTool("list_watchlist_items")).items.map(item => ({ isin: item.isin, name: item.name, type: item.securityType ?? null, quote: quoted(item.currentQuote),
226	    dayPercent: dayMove(item.currentQuote) })) };
227	}
228	import { firstSyncedOn, loadWealthEvents, scalableKnownIds, valuationHistory } from "@/lib/finance/net-worth";
229	import { serviceDb } from "@/lib/service-db";
230	import { loadWealthItems } from "@/lib/finance/wealth";
231	import { historyTradeRows, saveCharts } from "./charts";
232	import { calculateHistory, readHistoryInput, type TradeDetails } from "./history";
233	import type { ScalableExtras } from "./portfolio";
234	import { withScalable } from "./server";
235	
236	const LOGIN_NEEDED_MS = 600_000;
237	
238	export async function rebuildScalableHistory(connection: { id: string; workspace_id: string; portfolio: unknown }, timeZone: string, today: string): Promise<"saved" | "failed" | "skipped"> {
239	  const db = serviceDb();
240	  const [events, items] = await Promise.all([loadWealthEvents(db, connection.workspace_id), loadWealthItems(db, connection.workspace_id, true)]);
241	  const before = firstSyncedOn(valuationHistory(events, items, timeZone), scalableKnownIds([connection.portfolio as ScalableExtras | null]));
242	  if (!before) return "skipped";
243	  const failed = async (reason: string) => {
244	    const saved = await db.from("scalable_connections").update({ history_status: "failed", history_checked_on: today, history_error: reason.slice(0, 1000) }).eq("id", connection.id);
245	    if (saved.error) throw new Error(saved.error.message);
246	    return "failed" as const;
247	  };
248	  try {
249	    const known = await db.from("scalable_trade_details").select("provider_id, isin, price_text").eq("workspace_id", connection.workspace_id).limit(100000);
250	    if (known.error) throw new Error(known.error.message);
251	    const details: TradeDetails = {
252	      known: new Map((known.data ?? []).map(row => [row.provider_id, { isin: row.isin, price: row.price_text }])),
253	      remember: async (id, detail) => {
254	        const remembered = await db.from("scalable_trade_details").upsert({ workspace_id: connection.workspace_id, provider_id: id, isin: detail.isin, price_text: detail.price });
255	        if (remembered.error) throw new Error(remembered.error.message);
256	      },
257	    };
258	    const input = await withScalable(connection.id, connection.workspace_id, mcp => readHistoryInput(mcp, timeZone, before, details), fetch, LOGIN_NEEDED_MS);
259	    try { await saveCharts(connection.id, { charts: [], trades: historyTradeRows(input.rows), held: null }); } catch (cause) { console.error("Scalable trades were not saved", cause); }
260	    const result = calculateHistory(input);
261	    if (!result.ok) return await failed(result.reason);
262	    const saved = await db.rpc("replace_scalable_value_history", { p_connection_id: connection.id, p_checked_on: today,
263	      p_rows: result.days.map(day => ({ on_date: day.date, currency_code: "EUR", securities_minor: day.securitiesMinor.toString(), crypto_minor: day.cryptoMinor.toString(), cash_minor: day.cashMinor.toString(), total_minor: day.totalMinor.toString() })) });
264	    if (saved.error) throw new Error(saved.error.message);
265	    return "saved";
266	  } catch (error) {
267	    return failed(error instanceof Error ? error.message : "Scalable could not be read");
268	  }
269	}
