create function public.sync_scalable_wealth(p_connection_id uuid, p_items jsonb, p_portfolio jsonb) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; owner uuid; entry jsonb; previous public.wealth_items%rowtype; item public.wealth_items%rowtype;
  existing boolean; kept uuid[] := '{}'; changed integer := 0;
begin
  if p_connection_id is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_typeof(p_portfolio) is distinct from 'object' then
    raise exception 'Invalid Scalable sync' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  select owner_id into owner from public.workspaces where id = connection.workspace_id;
  for entry in select value from jsonb_array_elements(p_items) loop
    if entry - array['id','kind','name','currency_code','amount_minor','quantity_text','unit_price_text','cost_basis_minor','as_of'] <> '{}'::jsonb
      or entry->>'kind' not in ('holding','asset') then raise exception 'Unsupported Scalable wealth fields' using errcode = '22023'; end if;
    item := jsonb_populate_record(null::public.wealth_items, entry);
    if item.as_of > (now() at time zone coalesce((select timezone from public.workspace_settings where workspace_id = connection.workspace_id), 'Europe/Berlin'))::date then
      raise exception 'Valuation date cannot be in the future' using errcode = '22023'; end if;
    select * into previous from public.wealth_items where id = item.id for update;
    existing := found;
    if existing and previous.workspace_id <> connection.workspace_id then raise exception 'Wealth item belongs to another workspace' using errcode = '42501'; end if;
    if existing and (previous.kind <> item.kind or previous.currency_code <> item.currency_code) then raise exception 'Scalable position changed kind or currency' using errcode = '22023'; end if;
    kept := kept || item.id;
    if existing and previous.removed_at is null and previous.name = item.name and previous.amount_minor = item.amount_minor and previous.as_of = item.as_of
      and previous.quantity_text is not distinct from item.quantity_text and previous.unit_price_text is not distinct from item.unit_price_text
      and previous.cost_basis_minor is not distinct from item.cost_basis_minor then continue; end if;
    item.workspace_id := connection.workspace_id; item.version := coalesce(previous.version, 0) + 1; item.created_at := coalesce(previous.created_at, now());
    item.updated_at := now(); item.removed_at := null;
    insert into public.wealth_items select item.* on conflict (id) do update set name = excluded.name, amount_minor = excluded.amount_minor,
      quantity_text = excluded.quantity_text, unit_price_text = excluded.unit_price_text, cost_basis_minor = excluded.cost_basis_minor, as_of = excluded.as_of,
      version = excluded.version, removed_at = null, updated_at = excluded.updated_at;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), case when existing then public.wealth_record(previous) end, public.wealth_record(item));
    changed := changed + 1;
  end loop;
  -- Positions an earlier sync (from any connection of this workspace) wrote that Scalable no longer reports were sold.
  for previous in select w.* from public.wealth_items w where w.workspace_id = connection.workspace_id and w.removed_at is null and not (w.id = any(kept))
    and w.id in (select (jsonb_array_elements_text(c.portfolio->'itemIds'))::uuid from public.scalable_connections c where c.workspace_id = connection.workspace_id and c.portfolio ? 'itemIds')
    for update loop
    item := previous; item.removed_at := now(); item.version := previous.version + 1; item.updated_at := now();
    update public.wealth_items set removed_at = item.removed_at, version = item.version, updated_at = item.updated_at where id = item.id;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), public.wealth_record(previous), public.wealth_record(item));
    changed := changed + 1;
  end loop;
  update public.scalable_connections set portfolio = p_portfolio || jsonb_build_object('itemIds', to_jsonb(kept)), last_synced_at = now(), last_error = null
    where id = p_connection_id;
  return changed;
end;
$$;
revoke all on function public.sync_scalable_wealth(uuid, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.sync_scalable_wealth(uuid, jsonb, jsonb) to service_role;

"use client";

import { useCallback, useEffect, useState, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/button";
import { syncProblems } from "@/lib/sync-problems";

type Connection = { id: string; status: "active" | "expired" | "error"; last_synced_at: string | null; last_error: string | null; created_at: string };
type Data = { configured: boolean; connection: Connection | null };

const RESULTS: Record<string, string> = {
  connected: "Scalable Capital connected.",
  error: "The Scalable login was cancelled or failed. Try again.",
  invalid: "That Scalable link expired or was already used. Connect again.",
};
const date = (value: string | null) => value ? new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }) : "never";
const STATUS = { active: { label: "Active", tone: "bg-success-soft text-success" }, expired: { label: "Login ended", tone: "bg-danger/10 text-danger" }, error: { label: "Error", tone: "bg-danger/10 text-danger" } };

async function fetchStatus(): Promise<Data> {
  const response = await fetch("/api/scalable/connections", { cache: "no-store" });
  if (!response.ok) throw new Error("Scalable status is unavailable");
  return response.json();
}

async function openScalableLogin() {
  const response = await fetch("/api/scalable/connect", { method: "POST" });
  const body = await response.json().catch(() => ({}));
  if (!response.ok || !body.url) throw new Error(body.error ?? "The Scalable login could not be opened");
  window.location.assign(body.url);
}

export function ConnectScalable() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  return <div className="space-y-3 text-sm">
    <p className="font-medium">Connect Scalable Capital</p>
    <p className="text-muted-foreground">See holdings, cash and portfolio value on Accounts and Wealth. First turn on access in Scalable on the web under Profile → Security → Agentic Investing; read-only is enough.</p>
    {error && <p role="alert" className="text-danger">{error}</p>}
    <Button className="min-h-10" disabled={busy} onClick={() => { setBusy(true); setError(null); openScalableLogin().catch(failure => { setBusy(false); setError(failure instanceof Error ? failure.message : "The Scalable login could not be opened"); }); }}>
      {busy ? "Opening Scalable…" : "Connect Scalable Capital"}</Button>
  </div>;
}

const nextSync = (lastSynced: string | null) => lastSynced && new Date(lastSynced).toDateString() === new Date().toDateString() ? "tomorrow" : "within the hour";

export function ScalableCard({ children, setting }: { children: ReactNode; setting: ReactNode }) {
  const router = useRouter();
  const [data, setData] = useState<Data | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [highlight, setHighlight] = useState(false);
  const load = useCallback(() => fetchStatus().then(setData, () => setError("Scalable status is unavailable.")), []);
  useEffect(() => {
    let live = true;
    fetchStatus().then(loaded => {
      if (!live) return;
      setData(loaded);
      const result = new URLSearchParams(window.location.search).get("scalable");
      if (result && RESULTS[result]) setMessage(RESULTS[result]);
      setHighlight(result === "connected");
    }, () => { if (live) setError("Scalable status is unavailable."); });
    return () => { live = false; };
  }, []);

  async function act(run: () => Promise<Response>, done?: string) {
    setBusy(true); setError(null); setMessage(null);
    try {
      const response = await run();
      const body = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(body.error ?? "Something went wrong");
      if (done) setMessage(done);
      await load();
      router.refresh();
    } catch (failure) { setError(failure instanceof Error ? failure.message : "Something went wrong"); }
    setBusy(false);
  }
  const connection = data?.connection;
  const status = connection ? STATUS[connection.status] : null;
  const problem = connection ? syncProblems([{ name: "Scalable", status: connection.status, last_error: connection.last_error }])[0] : undefined;

  return <article id="scalable" aria-labelledby="scalable-connection" className={`scroll-mt-20 space-y-4 rounded-xl border bg-card p-5 ${highlight ? "border-brand ring-2 ring-brand/30" : "border-border"}`}>
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div className="min-w-0 space-y-1">
        <h3 id="scalable-connection" className="flex flex-wrap items-center gap-2 font-medium">Scalable Capital
          <span className="text-xs font-normal text-muted-foreground">Broker</span>
          {status && <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${status.tone}`}>{status.label}</span>}</h3>
        {connection && <p className="text-xs text-muted-foreground">Last sync {date(connection.last_synced_at)}{connection.status === "active" ? ` · next automatic sync ${nextSync(connection.last_synced_at)}` : ""}</p>}
      </div>
      {connection && data && <div className="flex flex-wrap gap-2">
        <Button size="sm" variant="outline" disabled={busy || !data.configured || connection.status !== "active"}
          onClick={() => void act(() => fetch(`/api/scalable/connections/${connection.id}/sync`, { method: "POST" }), "Scalable synced.")}>{busy ? "Working…" : "Sync now"}</Button>
        <Button size="sm" variant={connection.status === "active" ? "ghost" : "default"} disabled={busy || !data.configured}
          onClick={() => { setBusy(true); setError(null); openScalableLogin().catch(failure => { setBusy(false); setError(failure instanceof Error ? failure.message : "The Scalable login could not be opened"); }); }}>Reconnect</Button>
        <Button size="sm" variant="ghost" disabled={busy} onClick={() => { if (window.confirm("Disconnect Scalable Capital? Synced data stays."))
          void act(() => fetch(`/api/scalable/connections/${connection.id}`, { method: "DELETE" }), "Scalable Capital disconnected."); }}>Disconnect</Button>
      </div>}
    </div>
    {message && <p role="status" className="text-sm text-foreground">{message}</p>}
    {error && <p role="alert" className="text-sm text-danger">{error}</p>}
    {!data && !error && <p className="text-sm text-muted-foreground">Loading…</p>}
    {problem && <div role="alert" className="rounded-md border border-warning/40 bg-warning-soft px-3 py-2 text-sm text-warning"><p>{problem}</p>
      {connection?.last_error && <details className="mt-1 text-xs"><summary className="cursor-pointer">What Scalable said</summary><p className="mt-1 break-words">{connection.last_error}</p></details>}</div>}
    {children}
    {setting}
  </article>;
}
