function recordedEntries(item: WealthItem, events: HoldingEvents, timeZone: string) {
  const latest = new Map<string, ReturnType<typeof valuationHistory>[number] & Partial<WealthItem>>();
  for (const row of valuationHistory(events.filter(event => event.item_id === item.id), [item], timeZone)) {
    const known = latest.get(row.as_of);
    if (row.currency_code === item.currency_code && (!known || row.created_at > known.created_at)) latest.set(row.as_of, row);
  }
  const days = [...latest.values()].sort((a, b) => a.as_of.localeCompare(b.as_of));
  const first = days.findIndex(row => !row.removed);
  return days.slice(Math.max(first, 0)).map(row => ({
    date: row.as_of, calculated: false, trades: [],
