function tradesAddUp(trades: HoldingTrade[], sharesNow: bigint) {
  let held = 0n;
  for (const trade of trades) {
    held += signedShares(trade);
    if (held < -TOLERANCE) return false;
  }
  const gap = held - sharesNow;
  return gap <= TOLERANCE && gap >= -TOLERANCE;
