import type { WealthItem } from "@/lib/finance/wealth";
import { formatMoney } from "@/lib/finance/format";
import { directionOf, percentText } from "./delta";
import { toMinor } from "./live";
import type { ScalablePortfolio } from "./portfolio";

export function holdingRows(items: WealthItem[], portfolio: ScalablePortfolio, locale: string) {
  const held = new Set(portfolio.itemIds ?? []);
  return items.filter(item => item.kind === "holding" && held.has(item.id))
    .sort((a, b) => Number(BigInt(b.amount_minor) - BigInt(a.amount_minor)))
    .map(item => {
      const value = BigInt(item.amount_minor), cost = item.cost_basis_minor === null ? null : BigInt(item.cost_basis_minor);
      const money = (minor: bigint | string) => formatMoney(minor, item.currency_code, locale);
      return {
        id: item.id, name: item.name, value: money(value),
        position: `${item.quantity_text} × ${item.unit_price_text ? money(toMinor(item.unit_price_text, item.currency_code)) : "—"}`,
        gain: cost === null ? null : { direction: directionOf(value - cost), text: [`${value > cost ? "+" : ""}${money(value - cost)}`, percentText(value - cost, cost)].filter(Boolean).join(" · ") },
      };
    });
}

"use client";
import { useState } from "react";
import { NetWorthChart } from "@/components/net-worth-chart";
import type { Delta } from "@/lib/scalable/delta";
import type { ValueHistoryView } from "@/lib/scalable/value-history";

export const TONE = { up: "text-success", down: "text-danger", flat: "text-muted-foreground" };
export const period = (active: boolean) => `min-h-11 min-w-11 rounded-lg border px-3 text-sm ${active ? "border-brand bg-brand/10 font-medium text-foreground" : "border-border text-muted-foreground hover:text-foreground"}`;

export function DeltaText({ delta }: { delta: Delta | null }) {
  return delta ? <span className={`block text-xs ${TONE[delta.direction]}`}>{delta.amount}{delta.percent ? ` (${delta.percent})` : ""}</span> : null;
}

export function ValueHistory({ view, label }: { view: ValueHistoryView; label: string }) {
  const [by, setBy] = useState<"days" | "months">("days");
  const first = view.points[0], last = view.points.at(-1);
  const rows = view[by];
  const priced = rows.some(row => row.price !== null);
  if (!first || !last) return <p className="text-sm text-muted-foreground">No values are stored yet. They appear after a Scalable sync.</p>;
  return <div className="space-y-3">
    {view.points.length > 1
      ? <div><NetWorthChart label={label} points={view.points} byDate /><p className="flex justify-between gap-3 text-xs text-muted-foreground"><span>{first.label}</span><span>{last.label}</span></p></div>
      : <p className="text-sm text-muted-foreground">Only {first.label} is stored so far. The line appears once a second day has synced.</p>}
    {view.calculatedBefore && <p className="text-xs text-muted-foreground">Values before {view.calculatedBefore}, marked *, are calculated from your transactions and Scalable’s past prices. Older prices are further apart.</p>}
    <div role="group" aria-label="Table rows" className="flex gap-1.5">{([["days", "Days"], ["months", "Months"]] as const).map(([key, text]) =>
      <button key={key} type="button" aria-pressed={by === key} onClick={() => setBy(key)} className={period(by === key)}>{text}</button>)}</div>
    <div tabIndex={0} role="region" aria-label={`${label}, table`} className="max-h-80 overflow-auto rounded-lg border border-border">
      <table className="w-full text-sm">
        <thead className="sticky top-0 bg-card text-xs text-muted-foreground"><tr className="border-b border-border">
          <th scope="col" className="px-3 py-2 text-left font-medium">Date</th>
          {priced && <th scope="col" className="px-2 py-2 text-right font-medium">Price</th>}
          <th scope="col" className="px-3 py-2 text-right font-medium">Value</th>
        </tr></thead>
        <tbody>{rows.map(row => <tr key={row.date} className="border-b border-border align-top last:border-0">
          <th scope="row" className="px-3 py-2 text-left font-normal">{row.label}{row.calculated ? " *" : ""}
            {row.shares !== null && <span className="block text-xs text-muted-foreground">{row.shares} shares</span>}
            {row.trades && <span className="block text-xs text-brand">{row.trades}</span>}</th>
          {priced && <td className="px-2 py-2 text-right font-mono tabular-nums">{row.price ?? "—"}{row.priceChange?.percent && <span className={`block text-xs ${TONE[row.priceChange.direction]}`}>{row.priceChange.percent}</span>}</td>}
          <td className="px-3 py-2 text-right font-mono tabular-nums">{row.value}{priced ? row.change && <span className={`block text-xs ${TONE[row.change.direction]}`}>{row.change.amount}</span> : <DeltaText delta={row.change} />}</td>
        </tr>)}</tbody>
      </table>
    </div>
    <p className="text-xs text-muted-foreground">Each change compares with the row below it, and includes money moved in or out.{by === "days" ? " Showing up to the last 30 stored days." : " Each month shows its last stored day."}</p>
  </div>;
}

"use client";
import { ScalablePositionChart } from "@/components/scalable-position-chart";
import { DeltaText, TONE, ValueHistory } from "@/components/scalable-value-history";
import type { HoldingView } from "@/lib/scalable/holding-view";

const heading = "text-xs font-medium text-muted-foreground";
const cell = "px-2 py-2 text-right font-mono tabular-nums";

export function ScalableHoldingDetail({ view }: { view: HoldingView }) {
  return <div className="@container space-y-6">
    <dl className="grid grid-cols-2 gap-3 @lg:grid-cols-3 @3xl:grid-cols-4">
      {view.facts.map(fact => <div key={fact.label}><dt className="text-xs text-muted-foreground">{fact.label}</dt>
        <dd className={`break-words font-mono text-sm tabular-nums ${fact.direction ? TONE[fact.direction] : ""}`}>{fact.value}</dd></div>)}
      {view.isin && <div><dt className="text-xs text-muted-foreground">ISIN</dt><dd className="font-mono text-sm">{view.isin}</dd></div>}
    </dl>

    <section className="space-y-3">
      <h4 className={heading}>Value of your holding</h4>
      {view.historyNote && <p className="text-xs text-warning">{view.historyNote}</p>}
      <ValueHistory view={view.history} label={`${view.name} value by day`} />
    </section>

    <section className="space-y-3">
      <h4 className={heading}>Price</h4>
      <ScalablePositionChart name={view.name} views={view.prices} />
      {view.periods.length > 0 && <table className="w-full text-sm">
        <caption className="sr-only">Price change of {view.name} by period</caption>
        <thead className="text-xs text-muted-foreground"><tr className="border-b border-border">
          <th scope="col" className="py-2 pr-2 text-left font-medium">Period</th><th scope="col" className="px-2 py-2 text-right font-medium">Price then</th><th scope="col" className="py-2 pl-2 text-right font-medium">Change</th>
        </tr></thead>
        <tbody>{view.periods.map(row => <tr key={row.label} className="border-b border-border align-top last:border-0">
          <th scope="row" className="py-2 pr-2 text-left font-normal">{row.label}<span className="block text-xs text-muted-foreground">from {row.from}</span></th>
          <td className={cell}>{row.then}<span className="block text-xs text-muted-foreground">now {row.now}</span></td>
          <td className={`py-2 pl-2 text-right font-mono tabular-nums ${TONE[row.change.direction]}`}>{row.change.percent ?? "—"}<DeltaText delta={{ ...row.change, percent: null }} /></td>
        </tr>)}</tbody>
      </table>}
    </section>

    <section className="space-y-2">
      <h4 className={heading}>Your trades</h4>
      {view.trades.length ? <ul aria-label={`Trades of ${view.name}`} className="max-h-72 divide-y divide-border overflow-auto rounded-lg border border-border text-sm">
        {view.trades.map((trade, order) => <li key={order} className="flex items-start justify-between gap-3 px-3 py-2">
          <span>{trade.side} {trade.quantity}<span className="block text-xs text-muted-foreground">{trade.when}</span></span>
          <span className="text-right font-mono tabular-nums">{trade.amount ?? "—"}<span className="block text-xs text-muted-foreground">{trade.price ? `at ${trade.price}` : "price not stored"}</span></span>
        </li>)}
      </ul> : <p className="text-sm text-muted-foreground">No trades of this holding are stored.</p>}
      {view.trades.some(trade => trade.amount) && <p className="text-xs text-muted-foreground">Amounts are shares × price, without fees or taxes.</p>}
    </section>
  </div>;
}

